          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"24896bc1-7cb1-5a1d-9587-7d6ee5105b62","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مطالبة بأجرة متديد وقيمة تلف يف العن -إقرار الطرفن بفسخ العقد -إقرار املدعى عليها باالنتفاع بعد الفسخ ودفع التضمن بقوة قاهرة -اشتراط التضمن ولو بقوة قاهرة- عدم االلتفات للشرط ورد دعوى التضمن وإلزام املدعى عليها بدفع أجرة التمديد بقدر االنتفاع.","document_number":"3414350","case_number":"301581109","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"عقد -إجارة -مطالبة بأجرة متديد وقيمة تلف يف العن -إقرار الطرفن بفسخ العقد -إقرار املدعى عليها باالنتفاع بعد الفسخ ودفع التضمن بقوة قاهرة -اشتراط التضمن ولو بقوة قاهرة- عدم االلتفات للشرط ورد دعوى التضمن وإلزام املدعى عليها بدفع أجرة التمديد بقدر االنتفاع.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/1/17 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3414350 :‬‬\n                  ‫َر ْق ُم الدعوى‪301581109 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 3457251‬تاريخه‪1434/3/8 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬مطالبــة بأجــرة متديــد وقيمــة تلــف يف العــن ‪ -‬إقــرار‬\n‫الطرفــن بفســخ العقــد ‪ -‬إقــرار املدعــى عليهــا باالنتفــاع بعــد الفســخ‬\n‫ودفــع التضمــن بقــوة قاهــرة ‪ -‬اشــتراط التضمــن ولــو بقــوة قاهــرة‪-‬‬\n‫عــدم االلتفــات للشــرط ورد دعــوى التضمــن وإلــزام املدعــى عليهــا‬\n                                   ‫بدفــع أجــرة التمديــد بقــدر االنتفــاع‪.‬‬\n\n\n\n\n‫‪ .1‬قــول النبــي صلــى اهلل عليــه وســلم‪« :‬كل شــرط ليــس يف كتــاب اهلل‬\n‫فهــو باطــل وإن كان مئــة شــرط‪ ،‬قضــاء اهلل أحــق وشــرط اهلل أوثــق»‪.‬‬\n                                                      ‫أخرجــه البخــاري‪.‬‬\n‫‪ .2‬كل عقــد اقتضــى الشــرع ضمانــه لــم تغيــره الشــروط وعكســه‬\n                             ‫بعكســه‪[ .‬ينظــر‪ :‬الــروض املربــع ‪.]366/5‬‬\n‫‪ .3‬مــا ال يجــب ضمانــه ال يصيــره الشــرط مضمونــا ومــا يجــب ضمانــه‬\n‫ال ينتفــي الضمــان بشــرط نفيــه‪[ .‬ينظــر‪ :‬املغنــي ‪ ،115/8‬كشــاف‬\n                                                          ‫القنــاع ‪.]70/4‬‬\n\n\n\n\n                                                                                ‫‪366‬‬\n\f      ‫تقدمــت املدعيــة بدعــوى ضــد الشــركة املدعــى عليهــا بأنهــا اســتأجرت‬\n      ‫منهــا معرضــا بثمــن معلــوم ملــدة خمــس ســنوات وأنهــا طلبــت فســخ العقــد‬\n      ‫قبــل نهايــة الســنة الرابعــة واتفقــا علــى تاريــخ معلــوم ثــم طلبــت املدعــى‬\n      ‫عليهــا متديــد العقــد خمســة وأربعــن يومــا فوافقــت املدعيــة وحــدد ثمنــا‬\n      ‫معلومــا لهــذه املــدة ‪ ،‬عليــه وألن زجــاج املعــرض كان مكســورا حــن‬\n      ‫التســليم فقــد طلبــت املدعيــة إلــزام املدعــى عليهــا بــأن تدفــع ثمــن املــدة‬\n      ‫اإلضافيــة خمســة وأربعــن يومــا وقيمــة إصــاح الزجــاج وقيمــة فاتــورة‬\n      ‫الكهربــاء ‪ ،‬أقــر وكيــل املدعــى عليهــا بالعقــد وطلــب موكلتــه فســخه‬\n      ‫يف السنة الرابعة ثم طلبها متديده خمسة وأربعني يوما وأن زجاج املعرض‬\n      ‫مكســور إال أنــه دفــع بــأن موكلتــه لــم توافــق علــى الثمــن الــذي حددتــه‬\n      ‫املدعيــة لــذا فلــم تكمــل اخلمســة واألربعــن يومــا بــل ســلمت العقــار بعــد‬\n      ‫أربعــة عشــر يومــا مــن التاريــخ املتفــق عليــه وأمــا الزجــاج املكســور فلــم‬\n      ‫يكــن بتفريــط مــن موكلتــه بــل بســبب العاصفــة وأنكــر عــدم ســداد‬\n      ‫موكلتــه فاتــورة الكهربــاء لــذا فقــد طلــب صــرف النظــر عــن دعــوى‬\n      ‫املدعــي ‪ ،‬أقــر وكيــل املدعيــة بــأن موكلتــه اســتلمت العقــار بعــد أربعــة‬\n      ‫عشــر يومــا وأن كســر الزجــاج كان بســبب املطــر إال أنــه متســك مبــا‬\n      ‫ورد يف منطــوق وثيقــة العقــد بــأن موكلــه غيــر ضامــن ملــا يحصــل مــن‬\n      ‫تلــف ولــو كان بقــوة قاهــرة ‪ ،‬عليــه و ألن املدعــى عليــه وكالــة أقــر بــأن‬\n      ‫مدتهــا خمســة وأربعــون يومــا‬  ‫موكلتــه طلبــت مــن املدعيــة مهلــة إضافيــة ّ‬\n      ‫مــن‪2010/11/15 :‬م حتــى‪ 2010/11/30 :‬مدفوعــة األجــرة‪ ،‬ودفــع‬\n      ‫بــأن موكلتــه ملــا علمــت باملبالغــة يف قيمــة األجــرة امتنعــت مــن التمديــد‪،‬‬\n\n‫‪367‬‬\n\f‫ـنوية‬\n   ‫وهــذا الدفــع ال يلتفــت لــه‪ ،‬وألنــه صــادق علــى قيمــة العقــد السـ ّ‬\n‫وصــادق علــى طلــب مهلــة إضافيــة مدفوعــة األجــرة‪ ،‬وهــذا يعنــي طلبهــا‬\n‫متديــد املـ ّـدة بنفــس األجــرة‪ ،‬ومبــا أن أجــرة اليــوم الواحــد للعقــار محــل‬\n‫النــزاع هــو‪ :‬ثمانيــة آالف ومئــة وأربعــة وتســعون ريــاال وخمــس هلــات‬\n‫حســب القيمــة الســنوية التــي تصادقــا عليهــا أعــاه‪ ،‬ومبــا أن املدعــى‬\n‫عليــه وكالــة صــادق علــى أن موكلتــه لــم تس ـلِّم العقــار إال بتاريــخ‪:‬‬\n‫‪2010/11/29‬م‪ ،‬ومبــا أن املدعــي وكالــة قــد صــادق علــى أن موكلتــه‬\n‫اســتلمت العقــار محــل النــزاع بتاريــخ ‪2010/11/29‬م واســتالمه العقــار‬\n‫يف هــذا التاريــخ يعـ ّـد رض ـ ًا بفســخ العقــد‪ ،‬فتكــون الشــركة املدعــى‬\n‫عليهــا قــد اســتغلت العقــار محــل النــزاع ملــدة أربعــة عشــر يومــا‪ ،‬وألن‬\n‫وكيــل املدعيــة صــادق علــى أن الزجــاج اخلارجــي للعقــار محــل النــزاع‬\n‫تلــف باألمطــار‪ ،‬ودفــع بــأن موكلتــه اشــترطت علــى املدعــى عليهــا بأنهــا‬\n‫غيــر مســؤولة عــن أي ظــرف مــن الظــروف القاهــرة وأن تســتلم العقــار‬\n‫وجيــدة‪ ،‬وهــذا الدفــع ال أثــر لــه ألن كل‬  ‫بعــد العقــد بحالــة ســليمة ّ‬\n‫عقــد اقتضــى الشــرع ضمانــه لــم تغيــره الشــروط وعكســه بعكســه‬\n‫[ينظــر‪ :‬الــروض املربــع ‪ ،]366/5‬وألن مــا ال يجــب ضمانــه ال يصيــره‬\n‫الشــرط مضمونــا ومــا يجــب ضمانــه ال ينتفــي الضمــان بشــرط نفيــه‬\n‫[ينظــر‪ :‬املغنــي ‪ ،115/8‬كشــاف القنــاع ‪ ]70/4‬ولقــول النبــي صلــى اهلل‬\n‫عليــه وســلم‪( :‬كل شــرط ليــس يف كتــاب اهلل فهــو باطــل وإن كان‬\n‫مئــة شــرط‪ ،‬قضــاء اهلل أحــق وشــرط اهلل أوثــق)‪ ،‬لذلــك كلــه فقــد‬\n‫قــررت الدائــرة مايلــي‪ :‬أوال‪ :‬ألزمــت الشــركة املدعــى عليهــا بتســليم‬\n‫قيمــة اســتغاللها للعقــار محــل النــزاع مــن تاريــخ‪2010/11/16 :‬م‬\n‫حتــى تاريــخ‪2010/11/29 :‬م وقــدره‪ :‬مئــة وأربعــة عشــر ألفــا وســبعمئة‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫وثالثــة وعشــرون ريــاال‪ .‬ثانيــا‪ :‬ردت دعــوى املدعيــة يف مطالبتهــا بقيمــة‬\n      ‫واجهــات الزجــاج اخلارجيــة للعقــار محــل النــزاع وقيمــة فاتــورة الكهربــاء‬\n      ‫املذكــورة أعــاه وأخلــت ســبيل املدعــى عليهــا منهــا‪ ،‬وبذلــك حكمت‪،‬‬\n                  ‫لــم يقنــع الطرفان‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪301581109‬وتاريــخ‬\n      ‫‪ 1431/12/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 31100600‬وتاريــخ‬\n      ‫‪ 1431/12/03‬ه ـ الســبت املوافــق ‪1434/01/17‬ه ـ حضــر ‪..................‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..................‬بصفتــه‬\n      ‫وكيــا عــن ‪ ..............‬بوكالتــه عــن ‪ ..............‬بصفتــه شــريك ومديــر‬\n      ‫يف شــركة ‪...........................‬مبوجــب الوكالــة رقــم ‪ 37291‬وتاريــخ‬\n      ‫‪1430/4/15‬ه ــوحضر حلضــوره ‪ .................‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقم‪.....................‬بصفتــه وكيــا عــن ‪..................‬‬\n      ‫بوكالتــه عــن ‪ ......................‬بصفتــه نائــب رئيــس مجلــس املديريــن‬\n      ‫لشــركة ‪ ....................‬مبوجــب الوكالــة رقــم ‪ 38285‬وتاريــخ‬\n      ‫‪1430/7/20‬ه ـ وبعــد عــدة جلســات ادعــى املدعــي وكالــة قائــا‪:‬‬\n      ‫إن موكلتــي متلــك عقــار ًا يقــع يف طريــق ‪ ...‬مبدينــة جـ ّـدة ـ مركــز ‪...‬‬\n      ‫جتاريــة‪ ،‬وقــد أجــرت‬ ‫ّ‬    ‫‪،‬وهــو عبــارة مبنــى مكـ ّـون مــن عـ ّـدة معــارض‬\n      ‫موكلتــي الشــركة املدعــى عليهــا املعــرض رقــم‪ )1( :‬مــن العقــار‬\n\n‫‪369‬‬\n\f‫املوصــوف أعــاه ومســاحته‪ :‬خمســة آالف وســت مئــة وأربعــة وثمانــون‬\n‫متــرا مربعــا ملــدة خمــس ســنوات‪ ،‬ابتــداء مــن‪2006/11/15 :‬م ‪ ،‬بقيمــة‬\n‫قدرهــا‪ :‬اثنــان مليــون وتســع مئــة وخمســون ألفــا وعشــرون ريــاال‪ ،‬وقــد‬\n‫رغبــت الشــركة املدعــى عليهــا فســخ العقــد بنهايــة الســنة العقديــة‬\n‫الرابعــة والتــي تنتهــي بتاريــخ‪2010/11/15 :‬مفوافقــت موكلتــي‪ ،‬ويف‬\n‫تاريــخ‪2010/11/9 :‬م طلبــت املدعيــة مهلــة إضافيــة مدفوعــة األجــرة‬\n‫ومدتهــا خمســة وأربعــون يومــا مــن‪2010/11/15 :‬م‬          ‫ل ُتخلــي العقــار ّ‬\n‫حتــى‪2010/12/30 :‬م فوافقــت موكلتــي وقــدر أجرتهــا‪ :‬ثــاث مئــة‬\n‫وســبعة وثمانــون ألفــا ومئــة وخمســة وعشــرون ريــاال‪ ،‬ويف تاريــخ‪:‬‬\n‫‪2010/11/29‬م رغبــت الشــركة املدعــى عليهــا يف تســليم العقــار محــل‬\n‫الدعــوى‪ ،‬وعنــد اســتالم العقــار مــن قبــل موكلتــي يف هــذا التاريــخ‬\n‫فوجئــت موكلتــي بــأن واجهــات الزجــاج اخلارجــي الــذي علــى العقــار‬\n‫محــل الدعــوى غيــر موجــودة ومتلفــة‪ ،‬وقــد قامــت موكلتــي بإصــاح‬\n‫واجهــات الزجــاج بقيمــة قدرهــا‪ :‬ثــاث مئــة وثالثــون ألــف ريــال‪ ،‬كمــا‬\n‫أن الشــركة املدعــى عليهــا لــم تســدد فاتــورة الكهربــاء املتبقيــة عليهــا‬\n‫وقدرهــا‪ :‬ســبعة آالف وثــاث مئــة وثالثــة ريــاالت وخمســة وخمســون‬\n‫هللــة‪ ،‬أطلــب إلــزام املدعــى عليهــا مبــا يلــي‪ :‬أوال‪ :‬تســليم قيمــة واجهــات‬\n‫الزجــاج التــي أتلفتهــا املدعــى عليهــا وقيمتهــا‪ :‬ثــاث مئــة وثالثــون ألــف‬\n‫ريــال‪ .‬ثانيــا‪ :‬تســليم قيمــة فاتــورة الكهربــاء وقدرهــا‪ :‬ســبعة آالف‬\n‫وثــاث مئــة وثالثــة ريــاالت وخمســة وخمســون هللــة‪ .‬ثالثــا‪ :‬تســليم‬\n‫أجــرة املهلــة اإلضافيــة مــن‪2010/11/15 :‬م حتــى‪2010/12/30 :‬م‬\n‫وقدرهــا‪ :‬ثــاث مئــة وســبعة وثمانــون ألفــا ومئــة وخمســة وعشــرون ريــاال‪.‬‬\n‫فيكــون إجمالــي املبالــغ التــي تطالــب بهــا موكلتــي الشــركة املدعــى‬\n\n\n                                                                                     ‫‪370‬‬\n\f      ‫عليهــا مبلغــا قــدره‪ :‬ســبع مئــة وأربعــة وعشــرون ألفــا وأربعمئــة وثمانيــة‬\n      ‫وعشــرون ريــاال وخمســة وخمســون هللــة‪ ،‬هكــذا ادعــى‪ .‬وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬مــا ذكــره املدعــي وكالــة مــن‬\n      ‫أن موكلتــه متلــك العقــار املوصــوف أعــاه‪ ،‬وأن موكلتــي اســتأجرت‬\n      ‫املعــرض رقــم‪ )1( :‬ومســاحته‪ :‬خمســة آالف وســت مئــة وأربعــة وثمانــون‬\n      ‫متــرا مربعــا ملــدة خمــس ســنوات‪ ،‬ابتــداء مــن‪2006/11/15 :‬م ‪ ،‬بقيمــة‬\n      ‫قدرهــا‪ :‬اثنــان مليــون وتســع مئــة وخمســون ألفــا وعشــرون ريــاال‪ ،‬وأن‬\n      ‫موكلتــي رغبــت يف فســخ العقــد بنهايــة الســنة العقديــة الرابعــة والتــي‬\n      ‫تنتهــي بتاريــخ‪2010/11/15 :‬م فصحيــح‪ ،‬وأمــا ماذكــره أن موكلتــي‬\n      ‫مدتهــا خمســة وأربعــون يومــا مــن‪:‬‬   ‫طلبــت مــن املدعيــة مهلــة إضافيــة ّ‬\n      ‫‪2010/11/15‬م حتــى‪2010/12/30 :‬م مدفوعــة األجــرة فصحيــح‬\n      ‫وكان ذلــك مبوجــب كتــاب موكلتــي املــؤرخ يف‪2010/11/9 :‬م‪،‬ومبــا‬\n      ‫أن املدعيــة طلبــت مــن موكلتــي مبلغــا قــدره‪ :‬ثــاث مئــة وســبعة وثمانــون‬\n      ‫ألفــا ومئــة وخمســة وعشــرون ريــاال علــى مـ ّـدة التمديــد لــم توافــق‬\n      ‫موكلتــي لكــون هــذه القيمــة مبالــغ فيهــا‪ ،‬وخاطبــت موكلتــي املدعيــة‬\n      ‫بأنهــا ســوف تخلــي العقــار بتاريــخ‪2010/11/15 :‬م ويف هــذا التاريــخ‬\n      ‫لــم يحضــر أحــد مــن طــرف املدعيــة الســتالم املوقــع‪ ،‬وبعــد أربعــة‬\n      ‫أيــام حضــر منــدوب مــن جهــة املدعيــة وقــام مبعاينــة املوقــع وأفهمــت‬\n      ‫موكلتــي منــدوب املدعيــة بأنــه مــا زال يف املوقــع ممتلــكات ملوكلتــي‬\n      ‫كورشــة مجهــزة كاملــة خاصــة بالســيارات تقــدر قيمتهــا‪ :‬بخمســة‬\n      ‫ماليــن ريــال وســوف يتــم تركهــا يف املوقــع‪ ،‬فذكــر منــدوب املدعيــة‬\n      ‫ملوكلتــي بأنــه ســوف يقــوم مبناقشــة املالــك والــر ّد علــى موكلتــي‪ ،‬وقــد‬\n      ‫انتظــرت موكلتــي مـ ّـدة ولــم يــر ّد عليهــا منــدوب املدعيــة‪ ،‬وكانــت طيلــة‬\n\n\n‫‪371‬‬\n\f‫الفتــرة املاضيــة احلراســات التابعــة ملوكلتــي تعمــل يف املوقــع‪ ،‬وبعــد‬\n‫ذلــك اتفقــت موكلتــي مــع املدعيــة علــى أن يكــون التســليم يف تاريــخ‪:‬‬\n‫‪2010/11/29‬م‪ ،‬فاســتلمت املدعيــة العقــار محــل الدعــوى‪ ،‬وأمــا مــا‬\n‫ذكــره املدعــي وكالــة أنــه عنــد اســتالم العقــار مــن قبــل موكلتــه‬\n              ‫كان بــدون واجهــات زجــاج خارجــي فصحيــح‪ ،‬فقــد ّ‬\n‫حتطــم الزجــاج‬\n‫بســبب هبــوب عاصفــة قويــة وتلفــت مــع الواجهــات الزجاجيــة خمســة‬\n‫عشــر ســيارة مــن معــرض موكلتــي‪ ،‬فيكــون تلــف الزجــاج اخلارجــي‬\n‫ـماوية خارجــة عــن إرادة موكلتــي‪ ،‬وأمــا مــا ذكــره املدعــي‬    ‫بآفــة سـ ّ‬\n‫وكالــة بــأن موكلتــه قامــت بإصــاح واجهــات الزجــاج بقيمــة قدرهــا‪:‬‬\n‫ثــاث مئــة وثالثــون ألــف ريــال‪ ،‬فغيــر صحيــح‪ ،‬وأمــا مــا ذكــره املدعــي‬\n‫وكالــة أن موكلتــي لــم تســدد فاتــورة الكهربــاء املتبقيــة عليهــا‬\n‫وقدرهــا‪ :‬ســبعة آالف وثــاث مئــة وثالثــة ريــاالت وخمســة وخمســون‬\n‫هللــة فغيــر صحيــح‪ ،‬والصحيــح أنهــا ســددت كامــل الفواتيــر فتــرة‬\n‫اســتغاللها للموقــع‪ ،‬أطلــب رد دعــوى املدعيــة وإخــاء ســبيل موكلتــي‬\n‫منهــا‪ ،‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائــا‪:‬‬\n‫اســتلمت موكلتــي العقــار محــل النــزاع بتاريــخ‪2010/11/29 :‬م ‪،‬‬\n‫ومــا ذكــره املدعــى عليــه وكالــة أن موكلتــه قيمــة فاتــورة الكهربــاء‬\n‫فصحيــح‪ ،‬وأمــا مــا ذكــره أن الزجــاج اخلارجــي للعقــار محــل النــزاع تلف‬\n‫بســبب العواصــف فغيــر صحيــح‪ ،‬والصحيــح أنهــا تلــف بســبب األمطــار‪،‬‬\n‫لكــن املــادة الثانيــة عشــرة مــن العقــد البنــد الثانــي منهــا نــص علــى أن‬\n‫موكلتــي ال تعتبــر مســؤولة عــن أي ظــرف مــن الظــروف القاهــرة‪،‬‬\n‫والفقــرة الثامنــة عشــرة نصــت علــى أن تســلم املدعــى عليهــا العقــار بعــد‬\n‫وجيــدة‪ ،‬هكــذا أجــاب‪ .‬فبنــاء علــى مــا ســلف‪،‬‬   ‫العقــد بحالــة ســليمة ّ‬\n\n                                                                                     ‫‪372‬‬\n\f      ‫ومبــا أن املدعــي وكالــة صــادق علــى أن موكلــة املدعــى عليــه ســددت‬\n      ‫قيمــة فاتــورة الكهربــاء‪ ،‬ومبــا أن املدعــى عليــه وكالــة صــادق علــى‬\n      ‫مدتهــا خمســة وأربعــون‬   ‫أن موكلتــه طلبــت مــن املدعيــة مهلــة إضافيــة ّ‬\n      ‫يومــا مــن‪2010/11/15 :‬م حتــى‪2010/11/30 :‬ممدفوعــة األجــرة‪،‬‬\n      ‫ودفــع بــأن موكلتــه ملــا علمــت باملبالغــة يف قيمــة األجــرة امتنعــت مــن‬\n      ‫التمديــد‪ ،‬وهــذا الدفــع ال يلتفــت لــه‪ ،‬ألن صــادق علــى قيمــة العقــد‬\n      ‫ـنوية وصــادق علــى طلــب مهلــة إضافيــة مدفوعــة األجــرة‪ ،‬وهــذا‬        ‫السـ ّ‬\n      ‫يعنــي طلبهــا متديــد املـ ّـدة بنفــس األجــرة‪ ،‬ومبــا أن أجــرة اليــوم الواحــد‬\n      ‫للعقــار محــل النــزاع هــو‪ :‬ثمانيــة آالف ومئــة وأربعــة وتســعون ريــاال‬\n      ‫وخمــس هلــات حســب القيمــة الســنوية التــي تصادقــا عليهــا أعــاه‪،‬‬\n      ‫ومبــا أن املدعــى عليــه وكالــة صــادق علــى أن موكلتــه لــم تسـلِّم العقــار‬\n      ‫إال بتاريــخ‪2010/11/29 :‬م‪ ،‬ومبــا أن املدعــي وكالــة قــد صــادق علــى‬\n      ‫أن موكلتــه اســتلمت العقــار محــل النــزاع بتاريــخ‪2010/11/29 :‬م‬\n      ‫واســتالمها للعقــار يف هــذا التاريــخ يعـ ّـد رض ـ ًا بفســخ العقــد‪ ،‬فتكــون‬\n      ‫الشــركة املدعــى عليهــا قــد اســتغلت العقــار محــل النــزاع ملــدة أربعــة‬\n      ‫عشــر يومــا‪ ،‬ومبــا أنصــادق علــى أن الزجــاج اخلارجــي للعقــار محــل‬\n      ‫النــزاع تلــف باألمطــار‪ ،‬ودفــع بــأن موكلتــه اشــترطت علــى املدعــى‬\n      ‫عليهــا أنهــا غيــر مســؤولة عــن أي ظــرف مــن الظــروف القاهــرة‪ ،‬وأن‬\n      ‫وجيــدة وهــذا الدفــع ال أثــر لــه؛‬\n                                        ‫تســتلم العقــار بعــد العقــد بحالــة ســليمة ّ‬\n      ‫ألن كل عقــد اقتضــى الشــرع ضمانــه لــم تغيــره الشــروط وعكســه‬\n      ‫بعكســه [ينظــر‪ :‬الــروض املربــع ‪ ،]366/5‬وألنــه مــا ال يجــب ضمانــه ال‬\n      ‫يصــره الشــرط مضمونــا ومــا يجــب ضمانــه ال ينتفــي الضمــان بشــرط‬\n      ‫نفيــه [ينظــر‪ :‬املغنــي ‪ ،115/8‬كشــاف القنــاع ‪ ]70/4‬ولقــول النبــي ـ‬\n\n\n‫‪373‬‬\n\f‫صلــى اهلل عليــه وســلم ـ‪( :‬كل شــرط ليــس يف كتــاب اهلل فهــو باطــل‬\n‫وإن كان مئــة شــرط‪ ،‬قضــاء اهلل أحــق وشــرط اهلل أوثــق)‪ ،‬لذلــك‬\n‫كلــه فقــد قــررت مايلــي‪ :‬أوال‪ :‬ألزمــت الشــركة املدعــى عليهــا بتســليم‬\n‫قيمــة اســتغاللها للعقــار محــل النــزاع مــن تاريــخ‪2010/11/16 :‬م‬\n‫حتــى تاريــخ‪2010/11/29 :‬م وقــدره‪ :‬مئــة وأربعــة عشــر ألفــا وســبعمئة‬\n‫وثالثــة وعشــرون ريــاال‪ .‬ثانيــا‪ :‬رددت دعــوى املدعيــة يف مطالبتهــا بقيمــة‬\n‫واجهــات الزجــاج اخلارجيــة للعقــار محــل النــزاع وقيمــة فاتــورة الكهربــاء‬\n‫املذكــورة أعــاه وأخليــت ســبيل املدعــى عليهــا منهــا‪ ،‬وبذلــك قضيــت‪.‬‬\n‫وبإعــان احلكــم عليهمــا قــررا عــدم قناعتهمــا واســتعدا بتقــدمي الئحــة‬\n‫اعتراضيــة فجــرى تســليمهما نســخة مــن احلكم‪،‬وأفهمتهمــا بــأن لهمــا‬\n‫احلــق يف تقــدمي اعتراضهمــا خــال ثالثــون يومـ ًا اعتبــار ًا مــن هــذا اليــوم‪،‬‬\n‫حقهمــا يف‬ ‫وإذا انتهــت املـ ّـدة احملــددة ولــم يقدمــا الئحتهمــا ســقط ّ‬\n‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n                                         ‫ّ‬        ‫االعتــراض واكتســب احلكــم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/17‬ه ـ‬\n‫احلمد هلل وحده وبعد ويف يوم الســبت املوافق ‪1434/03/28‬هـ افتتحت‬\n‫اجللســة ‪ ،‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار‬\n‫الدائــرة احلقوقيــة السادســة رقــم‪ 3457251 :‬يف‪1434/03/08 :‬ه ـ‬\n‫ونــص احلاجــة منــه‪( :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــرر املوافقــة علــى احلكــم)‪ .‬ا‪ .‬ه ـ وللبيــان جــرى إثباتــه‬\n‫وأمــرت بالتهميــش علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى ســيدنا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/9‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس و أعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                       ‫‪374‬‬\n\f      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪ .................‬القاضــي باحملكمــة العامــة‬\n      ‫بجــدة واملســجل بع ــدد ‪ 3414350‬وتاريــخ ‪1434/1/17‬هــ‪ ،‬املتضمــن‬\n      ‫دعــوى شــركة ‪ ...‬ضــد شــركة ‪ ...................‬احملكــوم في ــه مبــا دون‬\n      ‫باطنه‪ ،‬وبدراسـة احلكم وصـورة ضبطـه والالئحة االعتراضية تقـررت‬\n      ‫املوافق ــة عل ــى احلكم‪ ،‬واهلل املوفق وصل ــى اهلل عل ــى نبينا محمد وعلـى‬\n                                                                ‫آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪375‬‬\n\f                        ‫كشاف املوضوعات‬\n\n‫الصفحة‬                       ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n          ‫مدع ناظر وقف بأجرة أحد محالت الوقف‬\n                                         ‫مطالبة ٍ‬\n  ‫‪5‬‬                                                           ‫إجارة‬    ‫‪1‬‬\n                     ‫من غائب تعذر إبالغه‬\n\n  ‫‪14‬‬        ‫مطالبة مؤجر بإخالء عقار من مستأجر غائب‬            ‫إجارة‬    ‫‪2‬‬\n\n         ‫مدع بأجرة معدة (شيول) ثبت ملكها له من‬\n                                             ‫مطالبة ٍ‬\n  ‫‪25‬‬                                                          ‫إجارة‬    ‫‪3‬‬\n                 ‫مدعى عليه عن فترة بقائها عنده‬\n\n          ‫مدعى عليه بتسليم سيارة بديلة يف عقد‬\n                                          ‫مدع ً‬‫مطالبة ٍ‬\n  ‫‪32‬‬     ‫إيجار منتهي بالتمليك ورفع اسمه من القائمة السوداء‬    ‫إجارة‬    ‫‪4‬‬\n                    ‫وتعويضه عن الضرر الذي حلقه‬\n\n         ‫إخالء عقار من مدعى عليه غائب وفرز ما يف العقار‬\n  ‫‪53‬‬                                                          ‫إجارة‬    ‫‪5‬‬\n            ‫من ممتلكات وإيداعها أو ثمنها يف بيت املال‬\n\n          ‫مدعى عليه غائبا تعذر إبالغه بإخالء‬\n                                        ‫ً‬    ‫مدع‬\n                                             ‫مطالبة ٍ‬\n  ‫‪59‬‬                                                          ‫إجارة‬    ‫‪6‬‬\n           ‫عقار استأجره وتسليم قيمة اإليجارات املتأخرة‬\n           ‫مطالبة مستأجر بإمضاء عقد إجارة وتسليم العني‬\n  ‫‪64‬‬      ‫املستأجرة يف عقد إجارة معلق على االنتهاء من بناء‬    ‫إجارة‬    ‫‪7‬‬\n                  ‫العني املؤجرة وجتهيزها واستالمها‬\n          ‫مدع فسخ عقد إجارة واستثمار وإخالء العني‬‫طلب ٍ‬\n          ‫املؤجرة وتسليمها له‪ ،‬من مدعى عليه مستأجر لم‬\n  ‫‪81‬‬                                                          ‫إجارة‬    ‫‪8‬‬\n         ‫يتمكن من االنتفاع من العني املؤجرة ألمر خارج عن‬\n                          ‫إرادة طريف العقد‬\n          ‫مطالبة مالك جديد بإلزام مدعى عليه رفع يده من‬\n  ‫‪91‬‬                                                          ‫إجارة‬    ‫‪9‬‬\n                  ‫عقاره املؤجر من مالكه السابق‬\n         ‫مطالبة مؤجر إخالء عقاره من مستأجره وسداد أجرة‬\n  ‫‪99‬‬     ‫بقائه بعد إخطاره برغبة املؤجر باإلخالء يف مدة أقل‬    ‫إجارة‬    ‫‪10‬‬\n                  ‫من املدة املشترطة لذلك يف العقد‬\n\f‫الصفحة‬                       ‫املوضوع‬                          ‫التصنيف‬   ‫م‬\n\n          ‫مطالبة مالك بإخالء عقار من مستأجر انتهى عقد‬\n ‫‪104‬‬                                                           ‫إجارة‬    ‫‪11‬‬\n                            ‫إيجاره‬\n\n         ‫دعوى بإخالء مستثمر لعقار استخدم يف تأجير عزاب‬\n ‫‪112‬‬                                                           ‫إجارة‬    ‫‪12‬‬\n                      ‫يف حي يسكنه عوائل‬\n\n         ‫دعوى مستأجر استرداد أجرة مدفوعة لتعرض العقار‬\n ‫‪118‬‬       ‫املستأجر لإلزالة وتقدير اختالف األجرة يف املدة‬      ‫إجارة‬    ‫‪13‬‬\n                       ‫املاضية الختالف املواسم‬\n\n ‫‪131‬‬         ‫دعوى مؤجر فسخ عقد إجارة محل وإخالئه‬               ‫إجارة‬    ‫‪14‬‬\n\n           ‫دعوى مستأجرة على شركة يف عقد إجارة منت ٍه‬\n         ‫بالتمليك تعرضت فيه السيارة املؤجرة إلى حادث فتم‬\n ‫‪137‬‬                                                           ‫إجارة‬    ‫‪15‬‬\n         ‫بيعها على غير املستأجر‪ ،‬وتطلب املدعية رفع اسمها‬\n                ‫من القائمة السوداء وتعويضها بسيارة بديلة‬\n\n         ‫مطالبة مؤجر من مستأجر لعقاره رغب يف فسخ عقد‬\n ‫‪147‬‬      ‫اإلجارة بإصالح ما أتلفه املستأجر و أحدثه وأجرة‬       ‫إجارة‬    ‫‪16‬‬\n                            ‫هذه املدة‬\n            ‫دعوى ناظر وقف فسخ عقد إجارة وقف والده‬\n ‫‪171‬‬       ‫وإخالئه من مستأجره مدة طويلة لتخلفه عن دفع‬          ‫إجارة‬    ‫‪17‬‬\n                              ‫األجرة‬\n         ‫مطالبة مؤجر بإخالء عقاره من مستأجره الذي تبلغ‬\n ‫‪177‬‬     ‫برسالة عن طريق البريد املمتاز بذلك يف املدة املتفق‬    ‫إجارة‬    ‫‪18‬‬\n                      ‫عليها لهذا اإلخطار يف العقد‬\n\n ‫‪184‬‬     ‫مطالبة بأجرة عقار من مستأجر سابق تعذر إبالغه‬          ‫إجارة‬    ‫‪19‬‬\n\n\n ‫‪192‬‬     ‫مطالبة بإخالء عقار من مستأجر غائب تعذر إبالغه‬         ‫إجارة‬    ‫‪20‬‬\n\n         ‫مطالبة بإخالء مستأجر عقارا انتهت مدة إجارته ومت‬\n ‫‪198‬‬                                                           ‫إجارة‬    ‫‪21‬‬\n                 ‫إخطاره خالل املدة املتفق عليها لذلك‬\n\f‫الصفحة‬                       ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n         ‫مطالبة مؤجر بقيمة حتسينات يف عقار استؤجر منه‬\n ‫‪202‬‬                                                        ‫إجارة‬    ‫‪22‬‬\n           ‫والعقد بني الطرفني نص على أنها ال تلزم املؤجر‬\n\n         ‫مطالبة مستأجر بإنفاذ عقد إجارة يف العني املؤجرة‬\n ‫‪208‬‬                                                        ‫إجارة‬    ‫‪23‬‬\n                    ‫املنتقلة ملكيتها ملالك جديد‬\n          ‫مطالبة بأجرة مدة بقاء املستأجر بعد انتهاء عقد‬\n ‫‪214‬‬       ‫اإلجارة والتعويض عن تأخره يف إخالء العقار‬        ‫إجارة‬    ‫‪24‬‬\n                             ‫املستأجر‬\n         ‫مطالبة بباقي قيمة أجرة سيارة على مستأجر يدعي‬\n ‫‪230‬‬                                                        ‫إجارة‬    ‫‪25‬‬\n                           ‫إعساره‬\n\n           ‫مطالبة بإخالء عقار ودفع أجرته يف دعوى غير‬\n ‫‪234‬‬                                                        ‫إجارة‬    ‫‪26‬‬\n                            ‫محررة‬\n\n          ‫مطالبة مستثمر ملنفعة عقار بإخالئه من مستأجره‬\n ‫‪239‬‬                                                        ‫إجارة‬    ‫‪27‬‬\n             ‫النتهاء العقد باألخطار وفق ما ورد ببنوده‬\n          ‫مطالبة بإخالء عقار من مستأجر يدفع بعدم عدم‬\n ‫‪243‬‬      ‫تقيد املالك املدعي بشرط غير منصوص عليه يف‬         ‫إجارة‬    ‫‪28‬‬\n                            ‫العقد‬\n            ‫مطالبة ناظر وقف بإخالء العقار املوقوف من‬\n ‫‪250‬‬       ‫مستأجره الذي لم تنته مدة إجارته ودفع األجرة‬      ‫إجارة‬    ‫‪29‬‬\n           ‫املستحقة وإصالح ما مت تغييره يف العني املؤجرة‬\n         ‫مطالبة مؤجر بفسخ عقد إجارته عقارا إلنشاء مصنع‬\n ‫‪268‬‬                                                        ‫إجارة‬    ‫‪30‬‬\n                 ‫لم يستخرج مستأجره رخصة له‬\n\n          ‫مطالبة وكيل ورثة مؤجر مستأجرا بتعديل قيمة‬\n ‫‪276‬‬                                                        ‫إجارة‬    ‫‪31‬‬\n                ‫اإلجارة لتغير أجرة املثل أو فسخها‬\n\n         ‫مطالبة مؤجر مستأجرا فسخ عقد اإلجارة لتأجيره‬\n ‫‪280‬‬                                                        ‫إجارة‬    ‫‪32‬‬\n            ‫املنفعة على غيره‪ ،‬والعقد بينهما ال مينع ذلك‬\n\n ‫‪286‬‬         ‫إخالء عقار من مستأجر غائب تعذر إبالغه‬          ‫إجارة‬    ‫‪33‬‬\n\f‫الصفحة‬                       ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n            ‫مطالبة مدعى عليه مستأجر بسداد أجرة عقار‬\n ‫‪291‬‬     ‫استأجره وإخالئه‪ ،‬واملدعى عليه يدفع بعيب يف العني‬     ‫إجارة‬    ‫‪34‬‬\n           ‫املؤجرة مع استخدامه له فترة طويلة دون مطالبة‬\n\n            ‫مطالبة بأجرة عني وسماع الدعوى غيابي ًا لتبلغ‬\n ‫‪301‬‬                                                          ‫إجارة‬    ‫‪35‬‬\n             ‫املدعى عليه لشخصه وتخلفه عن حضورها‬\n\n         ‫إخالء عقار موقوف لتبلغ مستأجره من خالل عنوانه‬\n ‫‪305‬‬     ‫املختار يف العقد بني الطرفني بإخطار الرغبة يف عدم‬    ‫إجارة‬    ‫‪36‬‬\n                            ‫التجديد‬\n\n\n ‫‪313‬‬           ‫مطالبة بإخالء عقار لعدم سداد األجرة‬            ‫إجارة‬    ‫‪37‬‬\n\n           ‫مطالبة مؤجر بإخالء عقاره من مستأجره الغائب‬\n ‫‪319‬‬      ‫الذي تعذر إبالغه المتناعه عن دفع األجرة وجتديد‬      ‫إجارة‬    ‫‪38‬‬\n                              ‫العقد‬\n\n            ‫مطالبة بإخالء عقار تغير مالكه ممن يدعي‬\n ‫‪324‬‬                                                          ‫إجارة‬    ‫‪39‬‬\n            ‫أسبقيته بشرائه من املدعي املطالب بإخالئه‬\n\n           ‫مطالبة بإخالء عقار من مدعى عليه غاب عن‬\n ‫‪331‬‬     ‫الدعوى مع تبلغه‪ ،‬ملماطلته يف السداد ومخالفة شرط‬      ‫إجارة‬    ‫‪40‬‬\n                  ‫يف العقد بتأجير العقار لعزاب‬\n\n           ‫مطالبة بفسخ عقد إجارة عقار من مقيم ملغادرته‬\n ‫‪344‬‬                                                          ‫إجارة‬    ‫‪41‬‬\n                  ‫النهائية للبالد وعدم سداد األجرة‬\n\n           ‫مطالبة بقيمة باقي أجرة عني يدفع املدعى عليه‬\n          ‫املستأجر باالتفاق على حسمها مقابل إصالحات‪،‬‬\n ‫‪348‬‬                                                          ‫إجارة‬    ‫‪42‬‬\n         ‫ومطالبة املدعي أيضا بباقي أجرة وحدة يف تلك العني‬\n                ‫لتجديد املستأجر املدعى عليه عقدها‬\n\n          ‫مطالبة بإخالء عقار من مستأجر مقيم غادر البالد‬\n ‫‪358‬‬                                                          ‫إجارة‬    ‫‪43‬‬\n                            ‫وتعذر إبالغه‬\n\f‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n         ‫مطالبة بأجرة متديد اتفق عليها طرفا عقد اإلجارة‪،‬‬\n ‫‪366‬‬       ‫وقيمة تلف يف العني املؤجرة بقوة قاهرة اشترط‬      ‫إجارة‬    ‫‪44‬‬\n                        ‫ضمانها يف العقد‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":366,"source_page_end":380,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f75b4ce4286709e158acceb138366522babd8b2ae4eba459294a235a85e73284","normalized_text_hash":"846fc0a56fc865bda6032227360e1ff0730efb97d5a06a600256cafd77149ad8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p366-3414350"},{"id":"471f3d53-6c5a-5ea2-8636-f5c6194dc005","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -عقد تصميم ديكور وفرش -منازعة يف تنفيذ عقد -دفع مبلغ كبير من قيمة العقد -املطالبة بندب خبير لتقدير قيمة األعمال -إيجابية تقرير اخلبير للمدعي -إلزام املدعى عليهما برد جزء من املبالغ املسلمة للمدعي .","document_number":"33277087","case_number":"24667","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/2","year":"1434","subject":"عقد -عقد تصميم ديكور وفرش -منازعة يف تنفيذ عقد -دفع مبلغ كبير من قيمة العقد -املطالبة بندب خبير لتقدير قيمة األعمال -إيجابية تقرير اخلبير للمدعي -إلزام املدعى عليهما برد جزء من املبالغ املسلمة للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/6/2 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                        ‫الص ِّك‪33277087 :‬‬\n                          ‫َر ْق ُم الدعوى‪24667 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3426549‬تاريخه‪1434/2/2 :‬هـ‬\n\n\n    ‫عقــد‪ -‬عقــد تصميــم ديكــور وفــرش‪ -‬منازعــة يف تنفيــذ عقــد‪ -‬دفــع‬\n    ‫مبلــغ كبيــر مــن قيمــة العقــد‪ -‬املطالبــة بنــدب خبيــر لتقديــر قيمــة‬\n    ‫األعمــال‪ -‬إيجابيــة تقريــر اخلبيــر للمدعــي‪ -‬إلــزام املدعــى عليهمــا بــرد‬\n                                           ‫جــزء مــن املبالــغ املســلمة للمدعــي ‪.‬‬\n\n\n\n\n                       ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه‪.‬‬\n\n\n\n    ‫ادعــى املدعــي بــأن موكلــه أبــرم عقــد مــع مكتــب تصميــم ديكــور‬\n    ‫والــذي ميثلــه املدعــى عليهمــا للقيــام بأعمــال الفــرش والديكــور يف‬\n    ‫منزلــه اخلــاص مقابــل مبلــغ معــن‪ ،‬وقــد اســتلم املدعــى عليهمــا مبلــغ‬\n    ‫كبيــر يف حــن أن العمــل الــذي قامــا بــه فيــه نقــص وتأخيــر‪ ،‬لــذا طلــب‬\n    ‫نــدب خبيــر إلحصــاء األعمــال التــي قــام بهــا املدعــى عليهمــا وإلزامهمــا‬\n    ‫بإكمــال النواقــص إن وجــدت‪ ،‬جــاء تقريــر اخلبيــر بــأن املبالــغ التــي‬\n    ‫ســلمت للمدعــى عليهمــا لــم تتــم أعمــال مقابلهــا بــل وبهــا عيــوب‬\n    ‫باإلضافــة إلــى أن مــدة العقــد قــد انتهــت ‪ ،‬لــذا حكمــت احملكمــة‬\n    ‫بإلــزام املدعــى عليهمــا بدفــع قيمــة الفــرق بــن املبلــغ املدفــوع مــن املدعــي‬\n    ‫وقيمــة األعمــال املنفــذة مــن املدعــى عليهمــا ‪ -‬اعتــرض املدعــى عليهمــا‬\n                  ‫علــى احلكــم ‪ -‬صــدق احلكــم مــن محكمــة اإلســتئناف ‪.‬‬\n‫‪5‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...............................‬القاضــي يف‬\n‫احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بالريــاض برقــم ‪ 24667‬وتاريــخ ‪1431/05/19‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 3191479‬وتاريــخ ‪ 1431/05/19‬ه ـ ففي‬\n‫يوم ال ــسبت املوافق‪ 1432/02/11‬هـ أفتتحت اجللسة الساعة ‪10 : 31‬‬\n‫وفيهــا حضــر ‪ ...................‬ســجل مدنــي ‪ ..................‬وكيــا ‪.................‬‬\n‫‪.....................‬‬    ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة يف شــرق الريــاض‬\n‫برقــم ‪ 6159‬يف ‪1432/1/19‬ه ـ وادعــى علــى احلاضــر معــه ‪...............‬‬\n‫اقامــة رقــم ‪ ...................‬وكيــا عــن ‪ .................‬بالوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بالريــاض برقــم ‪ 9172‬يف ‪1432/2/8‬ه ـ‬\n‫و‪ ..................‬الغائــب رغــم تبليغــه بواســطة ســكرتيره ‪...............‬‬\n‫حســب خطــاب التبليــغ املرفــق باملعاملــة قائــا يف دعــواه ان موكلــي‬\n‫اتفــق مــع مكتــب ‪ ......‬والــذي ميثلــه املدعــى عليهمــا علــى القيــام بأعمــال‬\n‫الفــرش والديكــور يف منزلــه اخلــاص مببلــغ ثمامنائــة وســبعة وخمســن‬\n‫الفــا وخمســمائة وســتة وســتني ريــاال وقــد اســتلم املدعــى عليهمــا مــن‬\n‫موكلــي ســبعمائة وواحــدا وتســعني الفــا وخمســمائة وســتة وســتني‬\n‫ريــاال اال ان العمــل الــذي قامــا بــه فيــه نقــص وتأخيــر يف تســليم االعمــال‬\n‫اطلــب نــدب خبيــر إلحصــاء األعمــال التــي قــام بهــا املدعــى عليهمــا‬\n‫والزامهمــا بإكمــال النواقــص واحضــار مالــم يتــم احضــاره ممــا اتفــق‬\n‫عليــه هــذه دعــواي فطلبــت مــن املدعــي بيــان االعمــال املتفــق عليهــا ومــا‬\n\n                                                                                             ‫‪6‬‬\n\f    ‫مت عملــه ومالــم يتــم فقــال ان االعمــال املتفــق عليهــا مرصــودة يف العقــد‬\n    ‫بينــي وبــن املدعــى عليهمــا وامــا االعمــال التــي اجنــزت فلــدي بيــان بهــا‬\n    ‫وكذلــك النواقــص لــدي بيــان بهــا وانــا مســتعد بتســليمه للمدعــى عليــه‬\n    ‫لالطــاع عليــه واالجابــة عنــه ثــم ابــرز املدعــي صــورة مــن العقــد وبيانــن‬\n    ‫باألعمــال املنجــزة والباقيــة وبعرضهــا علــى املدعــى عليــه قــال مــا ذكــره‬\n    ‫املدعــي مــن االتفــاق علــى اعمــال الديكــور والفــرش صحيــح واطلــب‬\n    ‫امهالــي للتأكــد مــن االرقــام و البيانــات التــي ابرزهــا املدعــي وقــد جــرى‬\n    ‫تزويــد املدعــى عليــه مــن قبــل املدعــي بصــور العقــد والبيانــات وافهــم‬\n    ‫املدعــى عليــه بــأن عليــه االجابــة يف اجللســة القادمــة وابــاغ املدعــى عليــه‬\n    ‫االخــر ‪ ...............‬باحلضــور ورفعــت اجللســة وتأجلــت حتــى يــوم االثنــن‬\n    ‫‪1432/4/24‬ه ـ الســاعة احلاديــة عشــر والنصــف ‪ .‬وبــاهلل التوفيــق ‪،‬‬\n    ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬احلمــد هلل‬\n    ‫وحــده وبعــد ففــي هــذا اليــوم االثنــن ‪1432/4/23‬ه ـ افتتحــت اجللســة‬\n    ‫وفيهــا حضــر املدعــي اصالــة وحضــر حلضــوره املدعــى عليــه وكالــة‬\n    ‫‪ ...........‬ولــم يحضــر املدعــى عليــه ‪ ............‬رغــم تبليــغ وكيلــه ‪.............‬‬\n    ‫مبوعــد هــذه اجللســة وأجــاب املدعــى عليــه ‪ .....‬بقولــه ان امللحوظــات‬\n    ‫التــي قدمهــا املدعــي يف البيانــن قــد اجبــت عنهــا وابــرز البيانــن وعليهــا‬\n    ‫اجاباتــه وبعرضهــا علــى املدعــي قــال ان كثيــرا ممــا جــاء يف اجابــات‬\n    ‫املدعــى عليــه غيــر صحيــح واطلــب تعيــن خبيــر لالطــاع علــى العقــد‬\n    ‫والبيانــات وحيــث ان املســألة تتعلــق بتطبيــق عقد للمدعــي واملدعى عليه‬\n    ‫علــى االعمــال املنجــزة ملحوظــات لــذا قــررت احالــة الطرفــن الــى هيئــة‬\n    ‫النظــر لالشــتراك مــع اهــل اخلبــرة واالفــادة عــن مــدى تطبيــق العقــد ومــا‬\n    ‫يوجــد عليــه مــن ملحوظــات وطلبــت مــن الطرفــن ابــراز العقــد والبيانــن‬\n\n\n‫‪7‬‬\n\f‫املقدمــة مــن املدعــي واملجــاب عليهــا مــن املدعــى عليــه فأبرزاهــا ورفعــت‬\n                                         ‫اجللســة لذلــك وعليــه حصــل التوقيــع ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم الســبت ‪1433/2/13‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي اصالــة ‪ ..................‬ســجل مدنــي‬\n‫‪ ....................‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ ......‬وقــد وردنــي‬\n‫قــرار هيئــة النظــر رقــم ‪ 1/1392‬يف ‪1432/10/23‬ه ـ الــذي جــاء فيــه‬\n‫انــه مت الوقــوف علــى االثــاث محــل النــزاع بحضــور ومشــاركة منــدوب‬\n‫مفروشــات ‪ ....‬الــذي مت اختيــاره مــن قبــل طــريف النــزاع وقــد مت اعــداد‬\n‫تقريــر مفصــل ملخصــه ‪ -1‬قيمــة العقــد ثمامنائــة وســتة واربعــون الــف‬\n‫ريــال ‪ -2‬قيمــة االثــاث املنفــذ واملســلم للمدعــي ثالثمائــة وســبعة وســبعون‬\n‫الفــا ومائتــان وواحــد وســبعون ريــاال ‪ -3‬قيمــة االثــاث الــذي لــم ينفــذ ولــم‬\n‫يســلم للمدعــي حتــى تاريخــه اربعمائــة وثمانيــة وســتون الفــا وســبعمائة‬\n‫وتســعة وعشــرون ريــاال ‪ -4‬اجمالــي املبالــغ التــي مت دفعهــا مــن املدعــي‬\n‫للمدعــى عليــه حســب اوراق املدعــى عليــه ســبعمائة وثمانــون الــف‬\n‫ريــال ‪ -5‬قيمــة النواقــص والعيــوب يف بعــض القطــع اثنــان واربعــون‬\n‫الفــا وخمســمائة ريــال وعليــه فيكــون مقــدار املبالــغ املدفوعــة والتــي‬\n‫لــم يــورد مايقابلهــا مــن االثــاث يف حــال اصــاح النواقــص هــو اربعمائــة‬\n‫والفــان وســبعمائة وتســعة وعشــرون ريــاال ا‪.‬ه ـ هــذا وقــد طلــب املدعــي‬\n‫تســليمه املبالــغ التــي لــم يــورد مــا يقابلهــا كمــا طلــب تســليمه قيمــة‬\n‫اصــاح مالــم يتــم اصالحــه هــذا وقــد جــرى االطــاع علــى العقــد املوقــع‬\n‫بــن الطرفــن وهــو ينــص علــى ان مــدة العقــد مائــة وثمانــن يومــا حتســب‬\n‫بعــد ســبعة ايــام مــن تاريــخ توقيــع العقــد املوقــع يف ‪1428/3/19‬ه ـ وقــد‬\n‫صــادق الطرفــان علــى ان هــذا العقــد هــو املوقــع بينهمــا هــذا وقــد قــرر‬\n\n\n                                                                                        ‫‪8‬‬\n\f    ‫املدعــى عليــه ان موكليــه ســبق ان تقدمــوا بدعــوى ضــد املدعــي بســبب‬\n    ‫تأخيــره دفــع الدفعــات املســتحقة فطلبــت منــه رقــم هــذه الدعــوى فوعــد‬\n    ‫بإحضــاره ورفعــت اجللســة وتأجلــت حتــى يــوم الغــد الســاعة الثانيــة عشــر‬\n    ‫والنصــف وبــاهلل التوفيــق احلمــد هلل وحــده وبعــد يف هــذا اليــوم االثنــن‬\n    ‫‪1433/6/2‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي اصالــة و املدعــى‬\n    ‫عليــه وكالــة ‪ ........‬كمــا حضــر ‪ ...............‬ســجل مدنــي ‪....................‬‬\n    ‫وكيــا عــن ‪ ..................‬بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n    ‫بالريــاض برقــم ‪ 64101‬يف ‪1431/8/29‬ه ـ وســألت املدعــى عليهما عما‬\n    ‫ذكــراه يف اجللســة الســابقة مــن وجــود دعــوى ســابقة ضــد املدعــي فقررا‬\n    ‫ان الدعــوى الســابقة كانــت ضــد ‪ ..............‬وليســت ضــد املدعــي وانهــا‬\n    ‫ال تتعلــق بــذات املوقــع املدعــى بــه يف دعوانــا هــذه وســألت الطرفــن هــل‬\n    ‫مــدة العقــد انتهــت فأجابــا جميعــا ان مــدة العقــد قــد انتهــت فبنــاء علــى‬\n    ‫ماتقــدم مــن الدعــوى واالجابــة ومــا جــاء يف تقريــر اهــل اخلبــرة مــن تقديــر‬\n    ‫االعمــال التــي مت تنفيذهــا مــن العقــد والعيــوب التــي فيــه واملبالــغ التــي‬\n    ‫دفعهــا املدعــي وحيــث صــادق الطرفــان علــى العقــد والعقــد موقــع مــن‬\n    ‫طرفــن الطــرف االول ‪ ..............‬واملوقــع ‪...................‬و‪ ............‬والطــرف‬\n    ‫الثانــي هــو املدعــي ‪ ............‬لــذا واشــارة مــا ورد يف تقريــر اخلبــراء‬\n    ‫مــن ان املبالــغ التــي ســلمت للمدعــى عليهمــا ولــم تتــم اعمــال مقابلهــا‬\n    ‫هــي اربعمائــة والفــا ريــال وســبعمائة وتســعة وعشــرون ريــاال والعيــوب‬\n    ‫املوجــودة يف العمــل قــدرت باثنــن واربعــن الفــا وخمســمائة ريــال وحيــث‬\n    ‫ان مــدة العقــد قــد انتهــت لــذا حكمــت بالــزام املدعــى عليهمــا بدفــع‬\n    ‫مبلــغ اربعمائــة وخمســة واربعــن الفــا ومائتــن وتســعة وعشــرين ريــاال‬\n    ‫للمدعــي وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة واملدعــى‬\n\n\n‫‪9‬‬\n\f‫عليهمــا عدمهــا فجــرى تســليم املدعــى عليهمــا نســخة احلكــم وافهمــا‬\n‫بــأن مــدة االعتــراض ثالثــون يومــا اعتبــارا مــن هــذا اليــوم فــإذا لــم يقدمــا‬\n‫االعتــراض خاللهــا فــإن حــق مــن لــم يقــدم اعتراضــه يف االســتئناف‬\n                    ‫يســقط ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪. .‬‬\n‫حيــث عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار التصديــق‬\n‫املــدون علــى ظهــر الصــك واملتضمــن مــا نصــه ( تظهيــرات الدائــرة‬\n‫الثانيــة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة الريــاض احلمــد‬\n‫هلل وحــده وبعــد‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 33277087‬وتاريخ‬\n‫‪1432/6/2‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ ..........................‬وأصدرنــا‬\n‫القــرار رقــم ‪ 3426549‬وتاريــخ ‪1434/2/2‬ه ـ املتضمــن باألكثريــة‬\n‫املصادقــة علــى احلكــم واهلل املوفــق قاضــي اســتئناف ‪ .............‬ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ‪ ....................‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ...........................‬ختمــه وتوقيعــه ) وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                          ‫‪10‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":5,"source_page_end":10,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"584614e86fc07edb7abedb0d892f239ff31a77b9c54bd601e3a2d57e3bc3bdfc","normalized_text_hash":"14027acd4d159eb4adfd4d9f59fa64f4520c4fee71a26726806355e1d9ee3c68","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p5-33277087"},{"id":"55e71098-bc3b-5b32-8c95-64600b663ae9","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد مقاولة -دعوى املدعي يف املطالبة بقيمة أعمال مقاولة -دفع املدعى عليه بالسداد وال بينة له -البينة على املدعي واليمن على من أنكر -احلكم بدفع املبلغ .","document_number":"34216111","case_number":"3415067","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/19","year":"1434","subject":"عقد مقاولة -دعوى املدعي يف املطالبة بقيمة أعمال مقاولة -دفع املدعى عليه بالسداد وال بينة له -البينة على املدعي واليمن على من أنكر -احلكم بدفع املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/5/19 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34216111 :‬‬\n                         ‫َر ْق ُم الدعوى‪3415067 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34295406‬تاريخه‪1434/8/13:‬هـ‬\n\n\n\n     ‫عقــد مقاولــة ‪ -‬دعــوى املدعــي يف املطالبــة بقيمــة أعمــال مقاولــة ‪ -‬دفــع‬\n     ‫املدعــى عليــه بالســداد وال بينــة لــه‪ -‬البينــة علــى املدعــي واليمــن علــى‬\n                                                ‫مــن أنكــر ‪ -‬احلكــم بدفــع املبلــغ ‪.‬‬\n\n\n\n\n     ‫قولــه صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                          ‫أنكــر ) ‪.‬‬\n\n\n\n     ‫ادعــى املدعــي بــأن لــه بذمــة املدعــى عليــه مبلغــا وقــدره خمســة وعشــرون‬\n     ‫الــف ريــال مقابــل إنشــاء بركــة مــاء وبيــارة وخــزان أرضــي وبيتــن‬\n                      ‫شــعبيني وطلــب إلــزام املدعــى عليــه تســليم هــذا املبلــغ ‪.‬‬\n     ‫أجــاب املدعــى عليــه بقولــه ‪ :‬إن مــا جــاء يف دعــوى املدعــي غيــر صحيــح‬\n     ‫مــن أنــه قــام بإنشــاء خــزان ومــاء وبيــارة وبيتــن شــعبيني والصحيــح أنــه‬\n     ‫قــام بعمــل بيــت شــعبي وخــزان مــاء فقــط باملشــاركة مــع شــخص آخــر‬\n     ‫مصــري اجلنســية مقابــل مبلغـ ًا وقــدره خمســة وعشــرون الــف ريــال وقــد‬\n     ‫اســتلم املدعــي كامــل حقــه‪ -‬ال بينــة للمدعــى عليــه على الســداد ورفض‬\n     ‫ميــن املدعــي ‪ -‬لقولــه صلــى اهلل عليــه وســلم ‪ ( :‬البينــة علــى املدعــي‬\n     ‫واليمــن علــى مــن أنكــر ) ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n\n‫‪11‬‬\n\f‫املبلــغ املدعــى بــه وإفهــام املدعــى عليــه بــأن لــه ميــن املدعــي متــى طلبهــا‬\n‫‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                       ‫اإلســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n‫العامــة بتبــوك وبنــاء علــى املعاملة احملالة لنــا من فضيلة رئيس احملكمة‬\n‫العامــة بتبــوك املكلــف برقــم ‪ 3415067‬وتاريــخ ‪1434/01/10‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3470495‬وتاريــخ ‪1434/01/10‬ه ـ اخلاصــة‬\n‫بدعــوى ‪.............‬باكســتاني اجلنســية ضــد ‪ .................‬بشــأن مطالبــة‬\n‫ماليــة ففــي يــوم األحــد املوافق‪1434/05/19‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪ ...................‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة رقــم ‪ ......................‬وادعــى علــى احلاضــر معــه‬\n‫يف مجلس احلكم ‪ ..................‬ســعودي اجلنســية مبوجب الســجل املدني‬\n‫ا يف دعــواه وهــو يجيــد التحــدث باللغــة العربيــة ‪:‬‬       ‫رقــم ‪ ...............‬قائ ـ ً‬\n‫إن لــي بذمــة املدعــى عليــه هــذا احلاضــر مبلغــا وقــدره خمســة وعشــرون‬\n‫الــف ريــال مقابــل إنشــائي لــه بركــة مــاء وبيــارة وخــزان أرضــي وبيتــن‬\n‫شــعبيني وقــد أمتمــت العمــل ولــم يســلمني املدعــى عليــه حقــي فاطلــب‬\n‫إلــزام املدعــى عليــه تســليمي هــذا املبلــغ هــذه دعــواي وأســأله اجلــواب‬\n‫ا ‪ :‬إن مــا جــاء‬\n                ‫‪ ،‬وبســؤال املدعــى عليــه عــن دعــوى املدعــي أجــاب قائ ـ ً‬\n‫يف دعــوى املدعــي غيــر صحيــح مــن أنــه قــام بإنشــاء خــزان ومــاء وبيــارة‬\n‫وبيتــن شــعبيني فغيــر صحيــح والصحيــح أنــه قــام بعمــل بيــت شــعبي‬\n‫وخــزان مــاء فقــط لــي باملشــاركة مــع شــخص آخــر مصــري اجلنســية‬\n                                                                                              ‫‪12‬‬\n\f     ‫مقابــل مبلغ ـ ًا وقــدره خمســة وعشــرون الــف ريــال وقــد إســتلم املدعــي‬\n     ‫كامــل حقــه منــي ولــم يبــق لــه يف ذمتــي أي حــق وال دعــوى هكــذا‬\n     ‫ا ‪ :‬إن مــا ذكــره املدعى‬     ‫أجــاب ‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائـ ً‬\n     ‫عليــه غيــر صحيــح والصحيــح مــا ذكــرت يف دعــواي ولــم أســتلم منــه‬\n     ‫أي مبلــغ مقابــل األعمــال املذكــورة وأمــام مــا ذكــره مــن مشــاركة‬\n     ‫معلــم مصــري يف العمــل فصحيــح ولكــن يف أعمــال اللياســة فقــط وقــد‬\n     ‫إســتلم حقــه مــن املدعــى عليــه والزال يف ذمــة املدعــى عليــه لــي املبلــغ‬\n     ‫الــذي ذكرتــه يف دعــواي لــم يســلمني إيــاه حتــى اآلن هكــذا اجــاب‬\n     ‫‪ ،‬فســألت املدعــى عليــه عــن بينتــه علــى مــا دفــع بــه مــن ســداده للمبلــغ‬\n     ‫ا ‪ :‬ليــس لــدي بينــة علــى الســداد حيــث أنــه بعــد‬   ‫املدعــى بــه فاجــاب قائـ ً‬\n     ‫إنتهــاء املدعــي مــن عملــه عنــدي ســلمته كامــل حقــه هكــذا أجــاب ‪،‬‬\n     ‫فأفهمــت املدعــى عليــه بــأن ليــس لــه إال ميــن املدعــي عليــه أنــه لــم يســتلم‬\n     ‫ا ‪ :‬إننــي ال أقبــل ميينــه هكــذا اجــاب‬    ‫منــه املبلــغ املدعــى بــه فأجــاب قائـ ً‬\n     ‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه باملبلــغ‬    ‫‪ ،‬فبنـ ً‬\n     ‫املدعــى بــه ودفعــه بســداده وعجــزه عــن البينــة وعدم قبولــه بيمني املدعي‬\n     ‫البينــة علــى املدعــي واليمــن علــى مــن‬  ‫ولقولــه صلــى اهلل عليــه وســلم ( ّ‬\n     ‫أنكــر ) وجلميــع مــا تقــدم فقــد ثبــت لــدي صحــة دعــوى املدعــي وألزمــت‬\n     ‫املدعــى عليــه ‪ ..................‬تســليم املدعــي ‪ ...............‬املبلــغ املدعــى بــه‬\n     ‫وقــدره خمســة وعشــرون الــف ريــال وأفهمــت املدعــى عليــه بــأن لــه ميــن‬\n     ‫املدعــي متــى طلبهــا وبذلــك حكمــت وبعرضــه عليهمــا قنــع املدعــي ولــم‬\n     ‫يقنــع املدعــى عليــه وطلــب إســتئناف احلكــم فأجيــب إلــى طلبــه وأفهــم‬\n     ‫مبقتضــى تعليمــات التمييــز وجــرى تســليمه نســخة مــن احلكــم يف هــذا‬\n     ‫اليــوم لتقــدمي الئحــة إعتراضيــة خــال ثالثــن يومـ ًا وإذا مضــت املــدة ولــم‬\n\n\n‫‪13‬‬\n\f‫يقــدم الئحــة ســقط حقــه يف اإلســتئناف واكتســب احلكــم القطعيــة‬\n‫ففهــم ذلــك ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففي يوم اإلثنني املوافق‪1434/08/29‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 10‬وقــد وردتنــا املعاملــة مــن محكمــة اإلســتئناف‬\n‫مبنطقــة تبــوك بخطــاب فضيلــة رئيســها املســاعد رقــم ‪341362933‬‬\n‫يف ‪1434/8/21‬ه ـ واملرفــق بــه قــرار التصديــق رقــم ‪ 34295406‬يف‬\n‫‪1434/8/13‬ه ـ الصــادر مــن الدائرة احلقوقية األولى املتضمن املصادقة‬\n‫علــى صــك احلكــم الصــادر منــا برقــم ‪ 34216111‬يف ‪1434/5/19‬ه ـ ‪،‬‬\n‫وللبيــان جــرى حتريــره ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/29‬ه ـ‬\n\n\n\n\n                                                                                    ‫‪14‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":11,"source_page_end":14,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3b0f07187554d29a6bacff76a5f2516c5d11e91700506c0f42435742486afb6d","normalized_text_hash":"59d405c9b0c4f88cd7811cc97353340b139f62bf5c966966121ff8953c40190f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p11-34216111"},{"id":"fcb19f51-27d2-5596-b0ad-bde8cb720852","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد مقاولة -مطالبة بإكمال أعمال مقاولة -مطالبة بغرامة الشرط اجلزائي -افهام املدعي بأن العقد باطل وغير منعقد وال تترتب عليه آثاره عن املطالبة بإكمال العمل وغرامة الشرط اجلزائي -افهام املتداعين أن من كان له دعوى محاسبة للمنفذ من العمل فله التقدم بها -تنازع اختصاص سلبي -عموم الوالية للمحكمة العامة -عدم جواز القضاء مبا لم يطلبه اخلصوم .","document_number":"32350265","case_number":"32543116","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/12/17","year":"1434","subject":"عقد مقاولة -مطالبة بإكمال أعمال مقاولة -مطالبة بغرامة الشرط اجلزائي -افهام املدعي بأن العقد باطل وغير منعقد وال تترتب عليه آثاره عن املطالبة بإكمال العمل وغرامة الشرط اجلزائي -افهام املتداعين أن من كان له دعوى محاسبة للمنفذ من العمل فله التقدم بها -تنازع اختصاص سلبي -عموم الوالية للمحكمة العامة -عدم جواز القضاء مبا لم يطلبه اخلصوم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1432/12/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪32350265 :‬‬\n                         ‫َر ْق ُم الدعوى‪32543116 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34344963‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n\n      ‫عقــد مقاولــة‪ -‬مطالبــة بإكمــال أعمــال مقاولــة‪ -‬مطالبــة بغرامــة‬\n      ‫الشــرط اجلزائــي‪ -‬افهــام املدعــي بــأن العقــد باطــل وغيــر منعقــد وال‬\n      ‫تترتــب عليــه آثــاره عــن املطالبــة بإكمــال العمــل وغرامــة الشــرط‬\n      ‫اجلزائــي ‪ -‬افهــام املتداعيــن أن مــن كان لــه دعــوى محاســبة للمنفــذ‬\n      ‫مــن العمــل فلــه التقــدم بهــا ‪ -‬تنــازع اختصــاص ســلبي‪ -‬عمــوم الواليــة‬\n          ‫للمحكمــة العامــة‪ -‬عــدم جــواز القضــاء مبــا لــم يطلبــه اخلصــوم ‪.‬‬\n\n\n\n\n      ‫قــال ابــن رجــب رحمــه اهلل يف القاعــدة السادســة واالربعــن‪ :‬يف العقــود‬\n      ‫الفاســدة هــل هــي منعقــدة أو ال قــال‪ ( :‬مــا ال يترتــب عليــه ذلــك أي‬\n      ‫مــا ال يترتــب عليــه حكــم مبنــي علــى التغليــب وال الســراية والنفــوذ‬\n      ‫كالنــكاح والبيــع وااليجــار واملعــروف مــن املذهــب أنــه غيــر منعقــد‬\n                                             ‫وتترتــب عليــه أحــكام الغصــب ) ‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم والــذي‬\n      ‫تبلــغ لغيــر شــخصه انــه اتفــق مــع احــدى املؤسســات والتــي كان ميثلهــا‬\n      ‫املدعــى عليــه وقــت العقــد وانــه كان وقتهــا هــو امللتــزم بالعقــد كــون‬\n      ‫صاحــب املؤسســة متوفــى وقــت حتريــره وذلــك ليبنــي أرضــه املوصوفــة‬\n\n‫‪15‬‬\n\f‫يف نــص القضيــة مببلــغ وقــدره خمســة وتســعون الــف ريــال وتكــون مــدة‬\n‫العقــد ثالثــة أشــهر ويتكفــل املدعــى عليــه بكافــة مــواد البنــاء وقــرر‬\n‫املدعــي أن املدعــى عليــه نفــذ جــزء ًا مــن املتفــق عليــه وبقــي عليــه أعمــال‬\n‫اخــرى لــم يكملهــا وطالــب املدعــى عليــه بإكمــال العمل املتبقي حســب‬\n‫العقــد وإلزامــه أيضـ ًا بغرامــة الشــرط اجلزائــي مــن ‪1432/7/7‬ه ـ وحتــى‬\n‫تاريــخ اقامــة الدعــوى مبلغـ ًا وقــدره مائــة وخمســون ريــاال عــن كل يــوم ‪-‬‬\n‫ابــرز املدعــي اصــل العقــد املبــرم مــع املدعــى عليــه ‪ -‬قــرر ناظــر القضيــة‬\n‫انــه بدراســة العقــد بــن الطرفــن وجــد ان يف العقــد جهالــة ظاهــرة‬\n‫حيــث لــم يبــن عــدد القواعــد وال عــدد األعمــدة وال نــوع الشــرفات‬\n‫وال عددهــا وال نــوع القواعــد وال نــوع الســيراميك وال مســاحة دورات‬\n‫ا يف ضبــط القضيــة) ولذلــك‬      ‫امليــاه ‪...‬الــخ (حســب مــا هــو مبــن تفصي ـ ً‬\n‫ا وال تترتــب عليــه آثــاره مــن اإللــزام بإكمــال العمــل‬    ‫يعتبــر العقــد باط ـ ً‬\n‫ونحــوه ولذلــك فقــد صــدر احلكــم بإفهــام املدعــي بــان العقــد باطــل غيــر‬\n‫منعقــد وال تترتــب عليــه اثــاره مــن املطالبــة بإكمــال العمــل والشــرط‬\n‫اجلزائــي ‪-‬قــرر املدعــي عــدم القناعــة ‪ -‬مت تزويــد املدعــى عليــه بصــورة‬\n‫مــن الصــك ‪-‬صــدر قــرار محكمــة االســتئناف باملالحظــة ومضمــون‬\n‫املالحظــة انــه تتــم الكتابــة لهيئــة النظــر لتقديــر املنفــذ مــن العمــل‬\n‫فأجــاب ناظــر القضيــة أن دعــوى املدعــي تضمنــت املطالبــة بإكمــال‬\n‫العمــل وغرامــة الشــرط اجلزائــي ولــم يطلــب املنفــذ مــن العمــل والبــد أن‬\n‫يكــون احلكــم القضائــي مالقــي للطلــب ومت إجــراء الــازم حيالــه ‪-‬‬\n     ‫صــدر قــرار محكمــة االســتئناف مبنطقــة حائــل باملصادقــة عليــه‪.‬‬\n\n\n\n\n                                                                                          ‫‪16‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بحائــل‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بحائــل برقــم ‪ 32543116‬وتاريــخ ‪ 1432/11/20‬ه ـ املقيــدة باحملكمــة‬\n     ‫برقــم ‪ 321483092‬وتاريــخ ‪ 1432/11/20‬ه ـ ففــي يــوم االحــد‬\n     ‫املوافــق‪ 1432/12/17‬ه ـ أفتتحــت اجللســة الســاعة ‪ 08 : 35‬وفيهــا‬\n     ‫حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وذلــك بشــأن‬\n     ‫دعــواه ضــد مؤسســة والتــي حتــدد لهــا موعــدا هــذا اليــوم الســاعة ‪00‬‬\n     ‫‪ 8 :‬وحضــر املدعــي ولــم يحضــر املدعــى عليــه وتلقيــت إفــادة رئيــس‬\n     ‫احملضريــن برقــم ‪ 321517978‬يف ‪1432/11/26‬ه ـ ومضمونهــا أنــه‬\n     ‫مت االتصــال علــى املدعــى عليــه وابالغــه باملوعــد وبســؤال املدعــي عمــا‬\n     ‫لديــه حــرر دعــواه قائــا اننــي املــك قطعــة االرض الواقعــة ب‪.........‬‬\n     ‫وحدودهــا شــماال ملــك وباقــي اجلهــات شــوارع وقــد اتفقــت مــع املدعــى‬\n     ‫عليــه علــى ان يبنــي لــي داخــل االرض مجلــس ومقلــط ودورتــن ميــاه‬\n     ‫ومطبــخ مببلــغ قــدره خمســة وتســعون الــف ريــال ويكــون مــدة العقــد‬\n     ‫ثالثــة اشــهر واتفقــت معــه علــى أن يكــون عقــد البنــاء مــن قبلــه وان‬\n     ‫يتكفــل باملــواد وكل مــا يلــزم لبنــاء املتفــق عليــه إال أنــه أخــل بالعقــد‬\n     ‫وأنــا معــد هــذه االرض لغــرض التجــارة فبنــاء علــى مــا ســلف وحيــث‬\n     ‫وردنــا تعميــم معالــي وزيــر العــدل رقــم ‪/13‬ت‪ 2593/‬يف ‪1426/2/30‬ه ـ‬\n     ‫بشــأن إيضــاح القضايــا الداخلــة يف اختصــاص ديــوان املظالــم ومنهــا‬\n     ‫الفقــرة (د) مــن أوال ونــص احلاجــة منهــا ( جميــع املقــاوالت املتعلقــة‬\n     ‫بإنشــاء مبــانٍ ونحوهــا متــى كان املقــاول متعهــد ًا بتوريــد املــؤن واألدوات‬\n\n‫‪17‬‬\n\f‫الالزمــة لهــا ) أ ‪ .‬ه ـ لــذا افهمــت املدعــي أن عليــه إقامــة دعــواه لــدى فــرع‬\n‫ديــوان املظالــم بحائــل وصرفــت النظــر عــن دعــواه لدينــا وبــه حكمــت‬\n‫وبإعــان احلكــم قنــع بــه املدعــي بشــهادة كاتبــه وبــه تعتبــر القضيــة‬\n‫منتهيــة ورفعــت اجللســة يف الســاعة ‪ 45:8‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/12/17‬هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االحــد املوافــق ‪1433/11/28‬ه ـ‬\n‫افتتحــت اجللســة يف الســاعة ‪ 11 : 11‬وفيهــا حضــر املدعــي وكنــت‬\n‫قــد تلقيــت خطــاب معالــي رئيــس املجلــس األعلــى للقضــاء رقــم ‪12319‬‬\n‫يف ‪1433/9/9‬ه ـ مرفق ـ ًا بــه قــرار جلنــة الفصــل يف تنــازع االختصــاص‬\n‫رقــم ‪/69‬ت وتاريــخ ‪1433/7/22‬ه ـ ونــص احلاجــة منــه ( وبالنظــر إلــى‬\n‫أن الدعــوى املاثلــة قــد صــدر فيهــا حكمــان احدهمــا مــن احملكمــة‬\n‫العامــة بحائــل برقــم ‪ 32350265‬يف ‪1432/12/17‬ه ـ واآلخــر مــن‬\n‫ديــوان املظالــم برقــم ‪/40‬ت ج ‪1433 / 1‬ه ـ يقضــي كل منهمــا بعــدم‬\n‫االختصــاص وملــا للمحكمــة العامــة مــن عمــوم الواليــة وبعــد التأمــل‬\n‫واملداولــة قــررت اللجنــة مــا يلــي أن القضيــة مــن اختصــاص القضــاء‬\n‫العــام ) ا ‪ .‬ه ـ وحيــث األمــر مــا ذكــر فقــد مت حتديــد موعــد هــذا اليــوم‬\n‫الســاعة ‪ 10 : 30‬وحضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يتــم‬\n‫إبالغــه وذكــر احملضــر أنــه مت االنتقــال ولــم يفتــح أحــد البــاب إلبالغــه‬\n                    ‫لــذا قــررت حتديــد موعــد آخــر إلبــاغ املدعــى عليــه‪.‬‬\n‫ويف جلســة أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه وتلقيت إفادة‬\n‫مديــر احلقــوق املدنيــة رقــم ‪ 3168/7/1/29‬بتاريــخ ‪1433/12/22‬ه ـ‬\n‫ومضمونــه بأنــه مت االنتقــال إلــى منــزل املذكــور وعنــد الوصــول إلــى‬\n‫املنــزل أفادنــا شــخص يدعــى‪ ....‬بأنــه متوفــى مــن أكثــر مــن ســنتني وإن‬\n\n\n                                                                                         ‫‪18‬‬\n\f     ‫الــذي يقــوم بأعمــال املؤسســة هــو ابنــه ‪ .........‬حســب احملضــر املرفــق لــذا‬\n     ‫قــررت حتديــد موعــد آخــر إلبــاغ املدعــى عليــه‪ /‬وحــدد موعــدا يــوم‬\n      ‫الســبت املوافــق ‪1434/1/3‬ه ـ الســاعة ‪ 8 : 30‬وعليــه حصــل التوقيــع ‪.‬‬\n     ‫ويف جلســة اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه أو مــن ميثلــه‬\n     ‫ولــم نتلــق رد ًا بشــأن تبليغــه رغــم أنــه متــت الكتابــة ملديــر شــرطة منطقــة‬\n     ‫حـ ــائــل ‪ 332223060‬وتاريـ ــخ ‪1433/12/22‬هـ وحيث األمر ما ذك ــر‬\n     ‫قــررت رفــع اجللســة يف الســاعة ‪ 9 : 18‬وحــدد موعــدا يــوم االثنــن املوافــق‬\n                           ‫‪1434/1/5‬ه ـ الســاعة ‪ 10 : 00‬وعليــه حصــل التوقيــع ‪.‬‬\n     ‫ويف جلســة اخــرى حضــر املدعــي وكنــت تلقيــت إفــادة مديــر إدارة تنفيذ‬\n     ‫األحــكام احلقوقيــة برقــم ‪ 13/7/1/29‬وتاريــخ ‪1434/1/3‬ه ـ ونــص‬\n     ‫احلاجــة منــه ( نفيدكــم بأنــه مت االنتقــال إلى منــزل ‪ ........‬املذكور وأفاد‬\n     ‫أهــل املنــزل بــأن ‪ ........‬ينــوب عــن والــده وحيــث أن ‪ ........‬غيــر موجــود يف‬\n     ‫حائــل حيــث أنــه تعــرض إلــى حــادث مــروري ومت تنوميــه يف مستشــفى يف‬\n     ‫مدينــة الريــاض حيــث أنــه يوجــد كســر يف ســاقه وعنــد إنهــاء العمليــة‬\n     ‫ســوف يحضر ) أ ‪ .‬هـ وقد وجدت محاضر مرفقه مبوجبه وحيث األمر‬\n     ‫ا‬\n     ‫مــا ذكــر فقــد قــررت ســماع الدعــوى غيابيـ ًا وحــرر املدعــي دعــواه قائـ ً‬\n     ‫لقــد اتفقــت مــع مؤسســة ‪ /‬وكان ميثلهــا وقــت العقــد والــذي كان وقتهــا‬\n     ‫هــو امللتــزم امامــي بالعقــد وبنــوده وااللتــزام بــه كــون صاحــب املؤسســة‬\n     ‫متــويف يف وقــت حتريــر العقــد وذلــك علــى أن يبنــي لــي يف ارضــي الواقعــة‬\n     ‫بالقاعــد وحدودهــا شــماال ملــك وباقــي اجلهــات شــوارع وكان العقــد‬\n     ‫ان يبنــي لــي مجلــس ومقلــط ودورتــن ميــاه ومطبــخ مببلــغ قــدره خمســة‬\n     ‫وتســعون الــف ريــال وتكــون مــدة العقــد ثالثــة اشــهر واتفقــت معــه علــى‬\n     ‫أن يكون عقد البناء من قبله أي من قبل املؤسســة وأن يتكفل باملواد‬\n\n\n‫‪19‬‬\n\f‫وكل مــا يلــزم لبنــاء املتفــق عليــه ولكــن نفــذ املدعــى عليــه مــن العقــد‬\n‫مــا يلــي اوال البنــاء عظمـ ًا بالكامــل مــع اللياســة ثانيــا مت تنفيــذ البويــات‬\n‫اخلارجيــة فقــط ثالثــا مت تنفيــذ القيشــان اخلــاص باملطبــخ ودورات امليــاه‬\n‫ثــم توقــف عــن العمــل وقــد بقــي مــن العمــل البويــات الداخليــة وتســليك‬\n‫الكهربــاء الداخلــي واخلارجــي وتركيبــات الكهربــاء مــع الكيبــل‬\n‫ومــواد الســباكة كاملــة كمــا أن هنــاك شــرط ًا جزائيـ ًا يتضمــن مبلغـ ًا‬\n‫قــدره مئــة وخمســون ريــا ًال عــن كل يــوم تأخيــر ولــذا فإنــي أطلــب الــزام‬\n‫املدعــى عليــه بإكمــال العمــل املتبقــي حســب العقــد والزامــه بغرامــة‬\n‫الشــرط اجلزائــي مــن تاريــخ ‪1432/7/7‬ه ـ وحتــى تاريــخ هــذا اليــوم مبلغا‬\n‫قــدره مئــة وخمســون ريــا ًال عــن كل يــوم هــذه دعــواي ثــم جــرى ســؤال‬\n‫املدعــي البينــة فقــال بينتــي العقــد احملــرر مــع املدعــى عليــه فأفهمتــه‬\n‫بأحضــار النســخة األصليــة مــن العقــد فأســتعد بذلــك ويف جلســة أخــرى‬\n‫حضــر املدعــي وابــرز اصــل العقــد املبــرم مــع املدعــى عليــه ونصــه (بســم‬\n‫اهلل الرحمــن الرحيــم احلمــد هلل رب العاملــن والصــاة والســام علــى‬\n‫اشــرف االنبياء واملرســلني وبعد فقد مت االتفاق بني طرف أول مؤسســة‬\n‫‪ /‬وطــرف ثــان ‪ /‬علــى إنشــاء مبنــى حســب املواصفــات االتيــة ‪ -1‬مجلــس‬\n‫رجــال مبســاحة ‪ 12*10‬كمبليــت مــن قواعــد وأعمــده وســقف شــينكو‬\n‫وعــازل يكــون مــن كرســي مــن ميــدة مــن ســبعني ســم واعمــده ‪20×50‬‬\n‫وقواعــد ‪ 80×80‬ويكــون ارتفــاع املجلــس ‪ 3.5‬متــر مــع شــرفات خارجيــة‬\n‫مــع نافذتــن مســاحة كل نافــذة ‪ 1×2‬وبــاب ‪2.20×1.5‬ســم مــن احلديــد‬\n‫املشــغول واللكســان ودورة ميــاه ومغاســل (‪ )3‬مــع القيشــان مبســتوى‬\n‫البــاب بحــث ال يزيــد ســعر املتــر مــن القيشــاني والســيراميك عــن ‪22‬‬\n‫ريــال ويكــون مــن اخلــزف ســعودي أو اســباني أو هنــدي أو حســب‬\n\n\n                                                                                         ‫‪20‬‬\n\f     ‫رغبــة الطــرف الثانــي بحيــث يتحمــل فــرق االســعار والبــاب يكــون مــن‬\n     ‫االملنيــوم ومــن داخــل خشــب ونافــذة للمغاســل ونافــذة للحمــام ومروحــة‬\n     ‫شــفط ارضيــات املجالــس مــن الصبــة ويقــوم الطــرف االول بأعمــال‬\n     ‫اللياســة والدهــان والكهربــاء وأنــواع الكهربــاء امريكــي أو الفــا أو‬\n     ‫التــرا والدهــان مــن جوتــن الداخلــي واخلارجــي وأدوات الســباكة مــن‬\n     ‫نبــرو واملغاســل أيرانــي او خــزف ســعودي او باكســتاني ويف حالــة‬\n     ‫رغبــة الطــرف الثانــي يف أي تغييــر يلتــزم بدفــع فــرق االســعار وكرســي‬\n     ‫عربــي وافرجنــي مــع اخلــاط والــدش ‪ -2‬املقلــط مبســاحة ‪ 8×5‬متــر مــن‬\n     ‫الشــينكو العــازل مــع الديكــورات اجلبســية اخلفيفــة ‪ +‬مغاســل عــدد‬\n     ‫(‪ )3‬مــن اخلــزف ايرانــي او باكســتاني ونافــذة مســاحتها ‪1×2‬متــر ‪2 +‬‬\n     ‫بــاب مــن احلديــد املشــغول واللكســان والبــاب يكــون ‪2.20×1.5‬متــر‬\n     ‫مــع اعمــال اللياســة داخلــي ‪ -3‬مطبــخ مســاحته ‪ 5×4‬متــر مــع بــاب‬\n     ‫وارضيــة ســيراميك وقيشــان متريــن مــع اجلبــس اخلفيفــه واعمــال اللياســة‬\n     ‫والدهــان ومجلــى داخــل املطبــخ ‪ +‬حمــام ومغاســل عــدد (‪ )2‬بجانــب‬\n     ‫املطبــخ حســب مواصفــات احلمــام الرجــال مايزيــد عــن االمتــار املتفــق‬\n     ‫عليهــا يحســب ســعر املتــر ‪ 490‬ريــال هــذا وقــد مت االتفــاق بــن الطرفــن‬\n     ‫علــى مبلــغ وقــدره خمســة وتســعون الــف ريــال ســعودي علــى النحــو‬\n     ‫التالــي دفعــة اولــى ثالثــون الــف ريــال عنــد بــدء توقيــع العقــد ‪ -2‬دفعــة‬\n     ‫ثانيــة ثالثــون الــف ريــال عنــد مرحلــة املبانــي والشــينكو ‪ -3‬دفعــة ثالثــة‬\n     ‫خمســة عشــر الــف ريــال عنــد اعمــال التشــطيب ‪ -4‬باقــي املبلــغ يكــون‬\n     ‫علــى دفعــات شــهرية مبقــدار الفــن وخمســمائة ريــال شــهريا حلــن انتهــاء‬\n     ‫العمــل يكــون تنفيــذ العمــل مــن مــدة شــهرين ونصــف إلــى ثالثــة اشــهر‬\n     ‫مالحظــة عنــد ارتفــاع ســعر أي مــن مــواد العمــل مــن تاريــخ توقيــع العقــد‬\n\n\n‫‪21‬‬\n\f‫يتحمــل الطــرف الثانــي فــرق األســعار ‪ -‬يخصــم مــن اجمالــي املبلــغ ثمــن‬\n‫البلــوك املوجــود باملوقــع واهلل املوفــق وهــو خيــر الشــاهدين طــرف اول‬\n‫طــرف ثانــي مالحظــة علــى الطــرف االول اجنــاز العمــل خــال الفتــرة‬\n‫احملــددة واي تأخيــر يلــزم بدفــع غرامــة تأخيــر مائــة وخمســن ريــال‬\n‫عــن كل يــوم مــن تاريــخ ‪1432/4/7‬ه ـ طــرف أول توقيعــه طــرف ثانــي‬\n                                                                   ‫توقيعــه ) أ ‪ .‬ه ـ‬\n‫وقــد كنــت قــد اطلعــت علــى صورتــه باملعاملــة وكنــت قــد درســت‬\n‫القضيــة وتأملتهــا وبدراســة العقــد بــن الطرفــن الــذي قدمــه املدعــي‬\n‫وجــدت أن العقــد فيــه جهالــة ظاهــرة وفاحشــة حيــث لــم يوضــح عــدد‬\n‫القواعــد وال عــدد االعمــدة وال نــوع الشــرفات وال عددهــا والنــوع‬\n‫النوافــذ وال نــوع الســيراميك وال مســاحة دورة امليــاه وال مســاحة‬\n‫نوافــذ الــدورة واملغاســل وال نوعهــا علــى التحديــد وال مســاحة مــكان‬\n‫املغاســل ولــم يذكــر عــدد نقــاط الكهربــاء وال اإلنــارة وال نوعيــة املــواد‬\n‫املســتخدمة فيهمــا علــى التحديــد ولــم يبــن نــوع الدهــان ولــم يذكــر‬\n‫ارتفــاع املقلــط وال املطبــخ وكراســي دورات امليــاه مــع اخلــاط والــدش‬\n‫لــم يبــن نوعهــا كمــا أن قيمــة العقــد دخلتهــا اجلهالــة بجعلهــا عرضــة‬\n‫للتغييــر عنــد ارتفــاع األســعار وجهالــة ثمــن البلــوك املــراد خصمــه مــن‬\n‫ا وحيــث أن دعــوى املدعــي الــزام‬      ‫القيمــة وكل ذلــك تصيــر العقــد باطـ ً‬\n‫املدعــى عليــه بإكمــال العقــد والزامــه بالشــرط اجلزائــي وحيــث أن مــا‬\n‫ا وال تترتــب عليــه آثــار مــن‬‫ذكرنــاه تصيــر العقــد مجهــو ًال ويكــون باطـ ً‬\n‫اإللــزام بإكمــال العمــل ونحــوه قــال ابــن رجــب رحمــه اهلل يف القاعــدة‬\n‫السادســة واالربعــن يف العقــود الفاســدة هــل هــي منعقــدة أو ًال قــال‬\n‫( مــا ال يترتــب عليــه ذلــك أي مــا ال يترتــب عليــه حكــم مبنــي علــى‬\n\n\n                                                                                        ‫‪22‬‬\n\f     ‫التغليــب وال الســراية والنفــوذ كالنــكاح والبيــع واالجــار فاملعــروف مــن‬\n     ‫املذهــب أنــه غيــر منعقــد وتترتــب عليــه احــكام الغصــب ) لذلــك كلــه‬\n     ‫فقــد أفهمــت املدعــي بــأن أتفاقــه مــع املدعــى عليــه علــى البنــاء موضــع‬\n     ‫النــزاع باطــل غيــر منعقــد وال تترتــب عليــه آثــار مــن املطالبــة إلكمــال‬\n     ‫العمــل واإللــزام بالشــرط اجلزائــي وبذلــك حكمــت وإذا كان للمدعــي‬\n     ‫للمنفــذ مــن العمــل فهــو‬\n                              ‫أو للمدعــى عليــه علــى اآلخــر دعــوى محاســبة ُ‬\n     ‫عليهــا وبإعــان احلكــم قــرر املدعــي عــدم القناعــة واســتعد بتقــدمي‬\n     ‫الئحــة فأفهــم باملراجعــة يــوم الســبت املوافــق ‪1434/1/10‬ه ـ التاســعة‬\n     ‫الســتالم صــورة الصــك ولــه حــق املعارضــة خــال مــدة قدرهــا ثالثــون‬\n     ‫يومــا مــن تاريــخ ‪1434/1/10‬ه ـ اذا مضــت املــدة ولــم يقــدم اعتراضــه‬\n     ‫خاللهــا فــإن حقــه يف االعتــراض يســقط كمــا قــررت تزويــد املدعــى‬\n     ‫عليــه بصــورة مــن الصــك وذلــك لإلعتــراض عليــه إن كان لــه اعتــراض‬\n     ‫خــال املــدة النظاميــة مــن تاريــخ اســتالمه ورفعــت اجللســة يف الســاعة‬\n     ‫‪ 9 : 5‬وعليــه حصــل التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                                                 ‫وصحبــه اجمعــن ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزائيــة بالريــاض‬\n     ‫واملكلــف بالشــخوص إلــى هــذه احملكمــة لإلجابــة على قــرار محكمة‬\n     ‫اإلســتئناف مبنطقــة حائــل مبوجــب خطــاب معالي األمني العــام للمجلس‬\n     ‫األعلــى للقضــاء رقــم ‪ 15303‬يف ‪1434/10/08‬ه ـ ففــي يــوم األحــد‬\n     ‫املوافــق‪ 1434/10/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 30‬وكنــت قــد‬\n     ‫اطلعــت علــى قــرار محكمــة االســتئناف مبنطقــة حائــل رقــم ‪3453466‬‬\n     ‫يف ‪1434/03/02‬ه ـ ونــص احلاجــة منــه (لوحــظ أنــه طاملــا أن فضيلتــه‬\n     ‫حفظــه اهلل أبطــل العقــد لوجــود الغــرر واجلهالــة فــكان األولــى علــى‬\n\n\n‫‪23‬‬\n\f‫ال وذلــك بتكليــف‬   ‫فضيلتــه إنهــاء القضيــة مبــا يقطــع اخلصومــة مســتقب ً‬\n‫قســم اخلبــراء باالشــتراك مــع أهــل اخلبــرة بتقديــر مــا نفــذ مــن العمــل‬\n‫وإجــراء محاســبة فيــه قطعـ ًا للنــزاع فعلــى فضيلتــه مالحظــة مــا ذكــر)‬\n‫ـاق لدعــوى‬‫أ‪.‬ه ـ وعليــه أجيــب اصحــاب الفضيلــة بــأن مــا حكمــت بــه مـ ٍ‬\n‫املدعــي وال ميكــن تكليــف قســم اخلبــراء مبــا طلبــه أصحــاب الفضيلــة‬\n‫ـاء علــى طلــب مــن املدعــي فاملدعــي يطالــب بتنفيــذ العقــد والــذي‬ ‫إال بنـ ً‬\n‫حكمنــا بأنــه باطــل ومتــى ماطلــب املدعــي ذلــك بعــد اكتســاب هــذا‬\n‫احلكــم القطعيــة فلــه ذلــك ولهــذا احلكــم ســوابق قضائيــة مصدقــه مــن‬\n‫مرجعهــا بهــذا اخلصــوص وليــس لــدي ســوى مــا حكمــت بــه وأجريتــه‬\n              ‫ورفعــت اجللســة يف الســاعة ‪ 01 : 45‬وعليــه حصــل التوقيــع‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪ 341379769‬وتاريــخ ‪1434/9/10‬ه ـ واملقيــدة‬\n‫لدينــا بتاريــخ ‪1434/10/27‬ه ـ املرفــق بهــا الصــك رقــم ‪32350265‬‬\n‫يف ‪1432/12/17‬ه ـ الصــادر مــن فضيلــة القاضــي‪ /‬اخلــاص بدعــوى‬\n‫ضــد مؤسســة بشــان دعــوى مقــاوالت معماريــة علــى الصفــة املوضحــة يف‬\n         ‫الصــك واملالحــظ عليهــا ســابقا بالقــرار رقــم ‪ 34186060‬يف‬\n‫‪1434/4/ 13‬ه ـ ـ جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه بعــد‬\n‫اإليضــاح األخيــر واهلل واملوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                         ‫وعلــى آلــه وصحبــه ‪.‬‬\n\n\n\n\n                                                                                     ‫‪24‬‬\n\f25\n\f26\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":15,"source_page_end":26,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e2a71d2a9058114afa70a730fdb26c01141584cd794ade584c3d6891d70f9c02","normalized_text_hash":"4df16a131286a8e0743d3778e413e6648bc7d3b9d3c09636101eec75a7ea9546","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p15-32350265"},{"id":"b9e20da7-2641-5b95-aa6f-170ae3f97a69","document_type":"judgment","category":"judicial","subcategory":"general","title":"جعالة -مطالبة بإعادة جزء من عوض جعالة لم ينفذ العامل فيه املطلوب -مرور املدى الزمني املتفق عليه إلنهاء املطلوب -إدعاء بعدم تسليم األوراق الالزمة إلنهاء املطلوب -عدم حضور املدعى عليه بعد اجللسة األولى قرينة ضده -حلف اليمن للمدعى باعتباره أقوى املتداعن -إلزام املدعى عليه بإعادة املبلغ املسلم","document_number":"33227400","case_number":"3387","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/3","year":"1434","subject":"جعالة -مطالبة بإعادة جزء من عوض جعالة لم ينفذ العامل فيه املطلوب -مرور املدى الزمني املتفق عليه إلنهاء املطلوب -إدعاء بعدم تسليم األوراق الالزمة إلنهاء املطلوب -عدم حضور املدعى عليه بعد اجللسة األولى قرينة ضده -حلف اليمن للمدعى باعتباره أقوى املتداعن -إلزام املدعى عليه بإعادة املبلغ املسلم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33227400 :‬تاريخه‪1433/5/3 :‬هـ‬\n                            ‫رقم الدعوى‪3387 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3430178‬تاريخه ‪1434/2/5 :‬هـ‬\n\n\n     ‫جعالــة ‪ -‬مطالبــة بإعــادة جــزء مــن عــوض جعالــة لــم ينفــذ العامــل فيــه‬\n     ‫املطلــوب ‪ -‬مــرور املــدى الزمنــي املتفــق عليــه إلنهــاء املطلــوب ‪ -‬إدعــاء‬\n     ‫بعــدم تســليم األوراق الالزمــة إلنهــاء املطلــوب ‪ -‬عــدم حضــور املدعــى‬\n     ‫عليــه بعــد اجللســة األولــى قرينــة ضــده ‪ -‬حلــف اليمــن للمدعــى‬\n     ‫باعتبــاره أقــوى املتداعــن ‪ -‬إلــزام املدعــى عليــه بإعــادة املبلــغ املســلم‬\n                                                                          ‫للمدعــي‪.‬‬\n\n\n\n\n     ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                         ‫حكمه‪.‬‬\n\n\n\n     ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه اتفــق معــه علــى أن يقــوم‬\n     ‫بإلغــاء احلكــم الصــادر عليــه مــن وزارة التجــارة عــن طريــق األمــارة‬\n     ‫واحملكمــة ووزارة الداخليــة وأن يقــوم بإلغــاء التعميــم الصــادر عليــه‬\n     ‫بخصوصــه وأن يقــوم بإصــدار أمــر تســليمه الســيارة احملجــوزة لــدى‬\n     ‫الشــرطة مقابــل خمســن ألــف ريــال كل هــذا خــال ثالثــة أشــهر ســلم‬\n     ‫لــه خمســة وعشــرين ألــف ريــال ‪ -‬ألن املدعــى عليــه لــم ينفــذ العمــل‬\n     ‫املطلــوب لــذا فيطلــب إلزامــه بــرد املبلــغ املســلم ‪ -‬أقــر املدعــى عليــه‬\n\n‫‪27‬‬\n\f‫باالتفــاق واســتالم املبلــغ إال أنــه أنكــر عــدم قيامــه بالعمــل املطلــوب‬\n‫ودفــع بــأن املدعــي لــم يســلمه األوراق املطلوبــة فتعــذر عليــه إنهــاء العمــل‬\n‫مــن جهتــه وأنــه طلــب منــه خــال املهلــة بالتوقــف لــذا فقــد طلــب رد‬\n‫دعــواه وأضــاف بــأن املدعــي متــى حلــف اليمــن علــى دعــواه فــا مانــع‬\n‫لديــه مــن رد املبلــغ لــه ‪ -‬حضــر املدعــي أصالــة ولــم يحضــر املدعــى عليــه‬\n‫بغيــر عــذر مقبــول فاعتبرتــه احملكمــة نــاكال وحلــف املدعــي علــى‬\n‫صحــة دعــواه بعــد حســم مــا أقــر بــأن املدعــى عليــه ســلمه لــه ‪ -‬إلقــرار‬\n‫املدعــى عليــه باســتالمه املبلــغ املدعــى بــه وعــدم إثباتــه الســتحقاقه لــه‬\n‫وتغيبــه عــن اجللســات بعــد ذلــك دون عــذر وألداء املدعــي اليمــن علــى‬\n‫صحــة دعــواه فقــد حكمــت الدائــرة بإلــزام املدعــى عليــه بــأن يدفــع إلــى‬\n‫املدعــي املبلــغ املدعــى بــه ومقــداره ثالثــة وعشــرون الــف ريــال ســيجرى‬\n‫إبالغــه بنســخه منــه لتمكينــه مــن االعتــراض ‪ -‬صــدق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالريــاض برقــم ‪ 3387‬وتاريــخ ‪1431/1/18‬هـ املقيدة‬\n‫باحملكمــة برقــم ‪ 3110498‬وتاريــخ ‪ 1431/01/18‬ه ـ يف يــوم الســبت‬\n‫‪1432/5/26‬ه ـ حضــر ‪ .......................‬ســجل رقــم ‪ .................‬بالوكالة‬\n‫عــن ‪ .....................‬ســعودي مبوجــب ســجل مدنــي رقــم ‪................‬‬\n‫مبوجــب صــك الوكالــة الصــادر مــن كتابــة العــدل الثانيــة بالريــاض‬\n‫برقــم‪ 77215‬وتاريــخ ‪1431/11/15‬ه ـ مجلــد ‪ 19059‬والتــي تخولــه حــق‬\n\n                                                                                        ‫‪28‬‬\n\f     ‫املطالبــة واملرافعــة واملدافعــة واإلقــرار واإلنــكار وطلــب اليمــن وردهــا‬\n     ‫وقبــول احلكــم وادعــى علــى احلاضــر معــه ‪ ...........................‬ســجل رقــم‬\n     ‫‪ .....................‬قائــا يف دعــواه اتفــق موكلــي مــع املدعــى عليــه احلاضــر‬\n     ‫بتاريــخ ‪1428/4/28‬ه ـ علــى أن يقــوم املدعــى عليــه بإلغــاء احلكــم‬\n     ‫الصــادر مــن وزارة التجــارة علــى موكلــي عــن طريــق أمــارة الريــاض‬\n     ‫واحملكمــة ووزارة الداخليــة وان يقــوم بإلغــاء التعميــم الصــادر علــى‬\n     ‫موكلي وان يقوم بإصدار أمر بتســليمه الســيارة احملجوزة لدى شــرطة‬\n     ‫منطقــة الريــاض مقابــل أتعــاب قدرهــا خمســون ألــف ريــال علــى أن يقــوم‬\n     ‫املدعــى عليــه بالعمــل املتفــق عليــه يف مــدة ال تتجــاوز ثالثــة أشــهر مــن‬\n     ‫تاريــخ توقيــع االتفــاق وقــد دفــع موكلــي خمســة وعشــرين ألــف ريــال مــن‬\n     ‫املبلــغ املتفــق عليــه إال أن املدعــى عليــه لــم ينفــذ العمــل املتفــق عليــه لــذا‬\n     ‫اطلــب احلكــم بإلزامــه بإعــادة الدفعــة التــي اســتلمها ومقدارهــا خمســه‬\n     ‫وعشــرون ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائــا‬\n     ‫مــا ذكــره املدعــى مــن اتفاقــي مــع موكلــه االتفــاق املذكــور بالتاريــخ‬\n     ‫املذكــور واملبلــغ املذكــور وأننــي اســتلمت منــه خمســة وعشــرين ألــف‬\n     ‫ريــال صحيــح ومــا ذكــره مــن أننــي لــم أقــم بتنفيــذ املتفــق عليــه غيــر‬\n     ‫صحيــح والصحيــح أننــي بــدأت باإلجــراءات إال أن املدعــي لــم يســلمني‬\n     ‫األوراق الالزمــة إال بعــد شــهر وخمســة عشــر يومــا مــن تاريــخ االتفــاق‬\n     ‫كمــا انــه قــال لــي بعــد ذلــك بعشــرة أيــام وقــف القضيــة ألننــي كلمتهــم‬\n     ‫وتوصلــت معهــم إلــى اتفــاق يعني بذلك الســوريني احملكوم لهم باحلكم‬\n     ‫املطلــوب إلغــاؤه لــذا فأننــي غيــر مســتعد بإعــادة الدفعــة التــي اســتلمتها‬\n     ‫ومتــى حلــف املدعــى أصالــة علــى عــدم صحــة كالمــي فإننــي مســتعد‬\n     ‫بإعــادة مــا اســتلمته بعــد حســم ألفــي ريــال أقرضتهــا إيــاه وثمــن تذكــرة‬\n\n\n‫‪29‬‬\n\f‫الريــاض جــدة اشــتريتها لــه هكــذا قــرر وبعــرض ذلــك علــى املدعــي‬\n‫قــال ســأراجع موكلــي لســؤاله عمــا ذكــر هكــذا قــرر فافهمتــه‬\n‫بــان عليــه إبــاغ موكلــه باحلضــور شــخصيا يف موعــد اجللســة القــادم‬\n‫فاســتعد بذلــك ورفعــت اجللســة لذلــك يف يــوم األربعــاء ‪1432/7/27‬ه ـ‬\n‫حضــر املدعــى أصالــة ولــم يحضــر املدعــى عليــه أو ينــوب عنــه ولــم يتقدم‬\n‫بعــذر وبعــرض اليمــن علــى املدعــى قــال أريــد أن يحلــف هــو علــى صحــة‬\n‫كالمــه وإذا حلــف قنعــت بيمينــه لــذا رفعــت اجللســة ويف يــوم الســبت‬\n‫‪1432/11/10‬ه ـ حضــر املدعــي وكالــة ‪ ..................‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ................‬أمــا املدعــى عليــه فلــم يحضــر لــذا‬\n‫رفعــت اجللســة ويف يــوم الســبت ‪1433/2/27‬ه ـ حضــر املدعــي وكالــة‬\n‫‪ .................‬ولــم يحضــر املدعــى عليــه أو مــن ينــوب عنــه ولــم يتقــدم بعــذر‬\n‫رقــم تبلغــه مبوعــد هــذه اجللســة شــخصيا وتوقيعــه علــى األمنــوذج حســب‬\n‫إفــادة احملضــر ‪ ...‬رقــم ‪ 321411123‬وحيــث لــم يحضــر املدعــى عليــه‬\n‫فقــد اعتبرتــه نــاكال وســألت املدعــي وكالــة هــل موكلــه مســتعد‬\n‫بــأداء اليمــن علــى صحــة دعــواه فأجــاب قائــا نعــم فأفهمتــه بإحضــاره‬\n‫ورفعــت اجللســة لذلــك ويف يــوم األحــد ‪1433/3/27‬ه ـ حضــر املدعــي‬\n‫أصالــة ولــم يحضــر املدعــى عليــه أو مــن ينــوب عنــه ولــم يتقــدم بعــذر لــذا‬\n‫فقــد طلبــت مــن املدعــي احللــف علــى صحــة دعــواه فاســتعد بذلــك ثــم‬\n‫حلــف قائــا واهلل العظيــم إننــي ســلمت للمدعــى عليــه ‪ ................‬خمســة‬\n‫وعشــرين ألــف ريــال مقابــل األعمــال التــي ذكرتهــا بالدعــوى وإنــه لــم‬\n‫ينفــذ شــيئا مــن األعمــال املتفــق عليهــا رغــم تســليمي لــه جميــع األوراق‬\n‫التــي طلبهــا أول مــا اتفقنــا وإننــي لــم أطلــب منــه التوقــف إال بعــد مضــي‬\n‫أكثــر ســنتني مــن االتفــاق دون أن يقــوم بــأي عمــل وإننــي لــم أخــذ منــه‬\n\n\n                                                                                           ‫‪30‬‬\n\f     ‫ســوى ألــف ريــال وإن يف ذمتــه لــي ثالثة وعشــرين ألف ريــال واهلل العظيم‬\n     ‫هكــذا حلــف ثــم قــال أطلــب احلكــم لــي بثالثــة وعشــرين ألــف ريــال ألن‬\n     ‫املدعــى عليــه ســلمني ألــف ريــال فقــط كمــا أمــن لــي تذكــرة ســفر مــن‬\n     ‫الريــاض إلــى جــدة علــى الدرجــة الســياحية قيمتهــا تقــل عــن ألــف ريــال‬\n     ‫هكــذا قــرر فبنــاء علــى مــا تقــدم وحيــث أقــر املدعــى عليــه باســتالمه‬\n     ‫املبلــغ املدعــى بــه وعــدم إثباتــه الســتحقاقه لــه وتغيبــه عــن اجللســات بعــد‬\n     ‫ذلــك دون عــذر وألداء املدعــي اليمــن علــى صحــة دعــواه فقــد حكمــت‬\n     ‫بإلــزام املدعــى عليــه بــأن يدفــع إلــى املدعــي املبلــغ املدعــى بــه ومقــداره‬\n     ‫ثالثــة وعشــرون ألــف ريــال وهــذا حكــم حضــوري يف غيــاب املدعــى‬\n     ‫عليــه وســيجرى إبالغــه بنســخه منــه لتمكينــه مــن االعتــراض عليــه يف‬\n     ‫مــدة ال تتجــاوز ثالثــن يومــا وإال ســقط حقــه يف االعتــراض واكتســب‬\n     ‫احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد حــرر يف‬\n                                                                        ‫‪1433/3/27‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........................‬القاضــي يف احملكمــة‬\n     ‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمة العامة بالرياض‪/‬املساعد برقم ‪ 3387‬وتاريخ ‪1431/01/18‬‬\n     ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 3110498‬وتاريــخ ‪1431/1/18‬ه ـ ففــي‬\n     ‫يــوم األربعــاء املوافــق‪ 1434/03/18‬ه ـ عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بالريــاض برقــم ‪ 34241639‬وتاريــخ ‪1434/02/11‬ه ـ‬\n     ‫واملرفــق بهــا قــرار تصديــق مــن دائــرة حقوقيــة خامســة برقــم ‪3430178‬‬\n     ‫وتاريــخ ‪1434/02/05‬ه ـ واملتضمــن مــا نصه بعــد املقدمة ‪ « :‬وباالطالع‬\n     ‫علــى مــا أجــاب بــه فضيلتــه واحلقــه بذيــل الصــك وصــورة ضبطــه بنــاء‬\n     ‫علــى قرارنــا رقــم ‪ 33390405‬وتاريــخ ‪1433/08/24‬ه ـ لــم يظهــر مــا‬\n\n\n‫‪31‬‬\n\f‫يوجــب االعتــراض علــى احلكــم ‪ .‬قاضــي اســتئناف ‪ ...................‬توقيــع‬\n‫وختــم ‪ ،‬قاضــي اســتئناف ‪ ..................‬توقيــع وختــم ‪ ،‬رئيــس الدائــرة‬\n‫‪ ................‬توقيــع وختــم « أ‪.‬ه ـ وحتــى ال يخفــى جــرى إحلاقــه وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪1434/3/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العاملــة بالريــاض املســاعد برقــم‬\n‫‪ 331675612‬وتاريــخ ‪1434/1/20‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ......................./‬املســجل برقــم‬\n‫‪ 33227400‬وتاريــخ ‪1433/5/3‬ه ـ واخلــاص بدعوى‪ ................./‬وكالة‬\n‫ضــد‪ .............../‬يف مبلــغ مــن املــال علــى الصفــة املوضحــة يف الصــك‬\n‫واملتضمــن حكــم فضيلتــه كمــا هــو موضــح بالصــك وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلتــه واحلقــه بذيــل الصــك وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪ 33390405‬وتاريــخ ‪1433/8/24‬ه ـ لــم يظهــر مايوجــب‬\n‫االعتــراض علــى احلكــم ‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":27,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"74eddb2bc27e9d4e604cc42759247beecb3f16af707a8634b46dbe19b625b1ee","normalized_text_hash":"e8a7109788f0292aa48a3d11b49b4b2e4048fd7daa9f5dbab1a591a8cee071ef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p27-33227400"},{"id":"34b758c7-52b7-5aa6-a20a-ae09d51c1516","document_type":"judgment","category":"judicial","subcategory":"general","title":"سمسرة -طلب سعي يف قيمة أرض -شهادة الشاهد -املعروف عرف ا كاملشروط شرط ا -إلزام املدعى عليه بدفع مبلغ السعي للمدعي -براءة ذمة املدعى عليه.","document_number":"349707","case_number":"33427681","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة يف محافظة اخلرج حضر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"سمسرة -طلب سعي يف قيمة أرض -شهادة الشاهد -املعروف عرف ا كاملشروط شرط ا -إلزام املدعى عليه بدفع مبلغ السعي للمدعي -براءة ذمة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 349707 :‬تاريخه‪1434/1/12 :‬هـ‬\n                        ‫رقم الدعوى ‪33427681:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3454614‬تاريخه‪1434/3/3 :‬هـ‬\n\n\n     ‫سمســرة ‪ -‬طلــب ســعي يف قيمــة أرض ‪ -‬شــهادة الشــاهد ‪ -‬املعــروف عرفـ ًا‬\n     ‫كاملشــروط شــرط ًا ‪ -‬إلــزام املدعــى عليــه بدفــع مبلــغ الســعي للمدعــي‬\n                                                     ‫‪ -‬بــراءة ذمــة املدعــى عليــه‪.‬‬\n\n\n\n                       ‫القاعدة الفقهية ( املعروف عرف ًا كاملشروط شرط ًا ) ‪.‬‬\n\n\n\n     ‫ادعــى املدعــي بأنــه قــام بالتوســط لبيــع فلــه للمدعــى عليــه مببلــغ مليــون‬\n     ‫ومائــة ألــف ريــال (كــدر) الســعي علــى البائــع وملــا رســا عليــه البيــع التــف‬\n     ‫مــن خلفــه واتصــل باملشــتري وأمت معــه البيــع ويطلــب إلزامــه بتســليم‬\n     ‫الســعي وقــدره ســبعة وعشــرون ألف ـ ًا وخمســمائة ريــال ـ بعــرض دعــوى‬\n     ‫املدعــي علــى املدعــى عليــه أنكــر صحــة مــا ذكــره املدعــي وقــال إن‬\n     ‫الصحيــح إنــه اتفــق مــع املشــتري علــى البيــع مباشــرة وبــدون توســط‬\n     ‫مــن أحــد املكاتــب العقاريــة ‪ ،‬حيــث قــام بعرضهــا علــى ســتة مكاتــب‬\n     ‫عقاريــة منهــا مكتــب املدعــي ‪ ،‬فجــاءه املشــتري يف بيتــه مســتد ًال‬\n     ‫بوجــود لوحــة البيــع علــى املنــزل فلــم يجــده فأخــذ رقمــه ورقــم هاتفــه مــن‬\n     ‫أخيــه واتصــل بــه حتــى مت البيــع بينــه وبــن املشــتري وقــد اشــترط علــى‬\n     ‫املشــتري أن الثمــن املذكــور صــاف ال ســعى منــه ألي مكتــب وهــو غيــر‬\n\n\n‫‪33‬‬\n\f‫مســتعد لتســليم املدعــي مــا يدعيــه ـ قــرر املدعــي ان املدعــى عليــه تعــرف‬\n‫علــى املشــتري بواســطته وأحضــر شــاهد ًا علــى ذلــك وهــو املشــتري‬\n‫وشــهد بشــهادة مضمونهــا أن الــذي دلــه علــى الفيــا هــو املدعــي ـ بعــرض‬\n‫الشــاهد ومــا شــهد بــه علــى املدعــى عليــه قــرر املدعــى عليــه أن الشــاهد‬\n‫ثقــة وعــدل إال أنــه أنكــر أن املدعــي هــو مــن دل املشــتري علــى الفيــا‬\n‫وأنــه لــم يبعــه عــن طريــق املكتــب بــل بــاع املشــتري بعــد مقابلتــه كمــا‬\n‫صــادق أن املشــتري واملدعــى جــاء لرؤيــة العمــارة فدخلوهــا وذهبــا كمــا‬\n‫إن املدعــى عليــه صــادق علــى أنــه قــال للمدعــي صاحــب املكتــب ( إذا‬\n‫هــذا الزبــون عــازم علــى الشــراء فخــذ منــه العربــون ـ بعــرض ذلــك علــى‬\n‫املدعــي أنكــر مــا ذكــره املدعــي عليــه والصحيــح أن املدعــى عليــه‬\n‫اتصــل باملدعــي بعدمــا واعــد املشــتري ملقابلتــه ألخــذ العربــون منــه وقــال‬\n‫( خــذ العربــون ال يهــون الرجــال مببلــغ مليــون ومائــة ألــف ريــال كــدر‬\n‫للعمــارة ) ومــا فيهــا مــن عفــش وبعرضــه علــى املدعــى عليــه صــادق عليــه‬\n‫ـ مت ســؤال املدعــي واملدعــى عليــه هــل لديهمــا مايــودان تقدميــه فأجابــا‬\n‫بــا ـ مت عــرض الصلــح بــن الطرفــن فلــم يســتطع التوصــل إليــه ـ بنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بأنــه عــرض‬\n‫عمارتــه للبيــع عنــد مكتــب املدعــي ‪ -‬وإلقــرار املدعــى عليــه أن املدعــي‬\n‫واملشــتري جــاءا إليــه لرؤيــة العمــارة ودخلوهــا ‪ -‬وإلقــرار املدعــى عليــه‬\n‫أنــه اتصــل علــى املدعــي وقــال لــه ( إذا الزبــون عــازم فأخــذ منــه العربــون)‬\n‫‪ -‬وملــا قــرره أهــل العلــم مــن أن املعــروف عرف ًا كاملشــروط شــرط ًا ـ صدر‬\n‫احلكــم علــى املدعــى عليــه بــأن يدفــع للمدعــي ســبعة وعشــرين ألف ـ ًا‬\n‫وخمســمائة ريــال ـ قنــع املدعــي باحلكــم وقــرر املدعــي عليــه اعتراضــه‬\n‫علــى احلكــم بالئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف ـ صــدق‬\n\n\n                                                                                        ‫‪34‬‬\n\f     ‫احلكــم مــن محكمــة االســتئناف ـ حضــر املدعــي يف جلســة أخــرى‬\n                                      ‫وقــرر اســتالمه املبلــغ احملكــوم لــه‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة يف‬\n     ‫محافظــة اخلــرج حضــر ‪ ...‬بالســجل املدنــي ‪ ...‬وادعــى علــى احلاضــر معــه‬\n     ‫‪ ...‬بالســجل املدنــي رقــم ‪ ...‬قائــا يف دعــواه انــه يف نهايــة شــهر جمــاد‬\n     ‫الثانيــة مــن هــذا العــام توســطت يف بيــع فلــة هــذا احلاضــر الواقعــة يف حــي‬\n     ‫‪ ...‬مبحافظــة (‪ )......‬مبليــون ومائــة الــف ريــال كــدر علــى املشــتري ‪ ...‬وملــا‬\n     ‫رســا عليــه البيــع التــف مــن خلفــي واتصــل باملشــتري مباشــرة وامت معــه‬\n     ‫البيــع وقــال مالــك دخــل باملكتــب لــذا اطلــب الزامــه بتســليمي الســعي‬\n     ‫وقــدره ســبعه وعشــرون الفــا وخمســمائة ريــال هــذه دعــواي وبســؤال‬\n     ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي مــن توســطه يف بيــع فلتــي‬\n     ‫التــي ذكــر علــى املشــتري ‪ ...‬غيــر صحيــح والصحيــح أنــا الــذي اتفقــت‬\n     ‫معــه علــى البيــع بهــذا املبلــغ مباشــرة وبدون توســط أي احــد من املكاتب‬\n     ‫العقاريــة حيــث عرضتهــا عنــد ســتة مكاتــب عقاريــة منهــا مكتــب‬\n     ‫هــذا احلاضــر املســمى مكتــب ‪ ...‬فجأنــي املشــتري يف بيتــي مســتدال‬\n     ‫بوجــود لوحــة البيــع علــى املنــزل فلــم يجدنــي فأخــذت رقمــه ورقــم هاتفــه‬\n     ‫مــن أخيــه وأتصلــت بــه حتــى مت البيــع بينــي وبينــه وقــد اشــترطت علــى‬\n     ‫املشــتري أن الثمــن املذكــور صــاف ال ســعي فيــه ألي مكتــب وأنــا غيــر‬\n     ‫مســتعد بتســليم املدعي ما يدعيه من مبلغ ألنه ال يســتحقه هذه اجابتي‬\n     ‫وبعــرض ذلــك علــى املدعــي قــال ان املدعــى عليــه تعــرف علــى املشــتري‬\n     ‫بواســطتي ولــدي البينــة علــى ذلــك ثــم أحضــر املدعــي معــه للشــهادة ‪...‬‬\n\n‫‪35‬‬\n\f‫بالســجل املدنــي رقــم ‪ ...‬وبســؤاله عمــا لديــه قــال كنــت أبحــث عــن‬\n‫عمــارة لشــرائها فوجدتهــا معروضــة مــن قبــل مكتــب هــذا احلاضــر يف‬\n‫اإلنترنــت فتواصلــت معــه وأتيتــه يف املكتــب وذهبــت وإيــاه لصاحبهــا‬\n‫ا أذن لنــا بالدخــول فأعجبتنــي فــزدت يف‬        ‫هــذا احلاضــر لرؤيتهــا وفع ـ ً‬\n‫ســومها حتــى أوصلتهــا إلــى مليــون ومائــة ألــف ريــال كــدر مبــا فيهــا مــن‬\n‫أثــاث عــدا غرفــة النــوم وخــال أســبوع اتصــل بــي املدعــي هــذا احلاضــر‬\n‫فأخبرتــه بقبولــي الشــراء بهــذا الســوم فطلــب منــي مهلــة لســؤال البائــع‬\n‫هــل يبيــع بهــذا الســوم أو ال وبعــد نصــف ســاعة أو أقــل اتصــل بــي وقــال‬\n‫تراهــم باعــوك واهلل يرزقــك فعرضــت عليــه أن أســلمه العربــون فقــال‬\n‫إننــي يف الريــاض وبعدهــا بيــوم جاءنــي املدعــى عليــه صاحــب العمــارة‬\n‫فقــال لــي أنــت أشــتريت البيــت فقلــت نعــم فســألته هــل الصــك بإســمك‬\n‫فقــال نعــم ولــن أبيعــك البيــت عــن طريــق املكتــب وســأبيعه عليــك أو‬\n‫علــى غيــرك فقلــت لــه إصلــح أنــت وصاحــب املكتــب علــى الســعي ألننــي‬\n‫ـاف إن طالــب‬  ‫أشــتريته منــه مبليــون ومائــة ألــف ريــال كــدر وليــس صـ ٍ‬\n‫بحقــه فقــال لــي أنــا بعتــك بهــذا املبلــغ أي مليــون ومائــة ألــف ريــال كــدر‬\n‫دون أثــاث فقبلــت وقــال أنــا أصلــح وإيــاه ثــم أخبــرت صاحــب املكتــب‬\n‫مبــا حصــل منــه وقلــت لــه حقــك مــن الســعي عنــد البائــع وهــذا مــا لــدي‬\n‫وبــه أشــهد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال الشــاهد‬\n‫ثقــة وشــهادته صحيحــة ســوى قولــه أن املدعــي قــال لــه تراهــم باعــوك‬\n‫ال‬\n‫يقصدنــي فأنــا لــم أبعــه عــن طريــق املكتب وإمنــا بعته بعــد مقابلته وفع ً‬\n‫جاءنــي املشــتري وصاحــب املكتــب لرؤيــة العمــارة فدخلوهــا وذهبــا وقد‬\n‫جاءنــي صاحــب املكتــب بزبونــن قبلــه كمــا أننــي اتصلــت بصاحــب‬\n‫املكتــب وقلــت لــه إذا هــذا الزبــون عــازم علــى الشــراء فخذ منــه العربون‬\n\n\n                                                                                        ‫‪36‬‬\n\f     ‫فــرد علــي وقــال ليــس لــي دخــل وبــع بيتــك أنــت وأغلــق الســماعة بوجهــي‬\n     ‫هكــذا قــرر وبعرضــه علــى املدعــي قــال مــا ذكــره املدعــى عليــه أخيــر ًا‬\n     ‫غيــر صحيــح والصحيــح أن املدعــى عليــه اتصــل بــي بعدمــا واعــدت‬\n     ‫املشــتري مبقابلتــه ألخــذ عربــون منــه وقــال لــي تكفــى خــذ منــه عربــون‬\n     ‫ال يهــون الرجــال علــى أســاس أن الثمــن مليــون ومائــة ألــف ريــال كــدر‬\n     ‫للعمــارة ومــا فيهــا مــن عفــش ألننــي اشــتريت عمــارة ‪ ...‬يف الريــاض وال‬\n     ‫أريــد أن تضيــع البيعــة علــي فطلبــت منــه رقــم ‪ ...‬ألطلــب منــه مهلــة يــوم‬\n     ‫أو يومــن ريثمــا يحضــر املشــتري الثمــن لعمــارة املدعــى عليــه فقــال‬\n     ‫مــادام املســألة يــوم أو يومــن فــا حاجــة أن تتصــل بــال‪ ...‬أهــم شــيء ال‬\n     ‫يهــون املشــتري هكــذا قــرر وبعرضــه علــى املدعــى عليــه قــال كالمــه‬\n     ‫هــذا صحيــح وقــد اتصلــت بــه بعــد هــذا الــكالم بيــوم فقــال ليــس‬\n     ‫لــي دخــل ببيتــك هكــذا قــرر فســألتهما هــل بقــي لديهمــا مــا يرغبــان‬\n     ‫تقدميــه لضبطــه فقــال كل واحــد منهمــا ال فعرضــت عليهمــا الصلــح‬\n     ‫ورغبتهمــا فيــه فلــم يســتجيبا ومبــا أنــه مت تأمــل القضيــة فلمــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة واقــرار املدعــى عليــه بأنــه عــرض عمارتــه للبيــع‬\n     ‫عنــد مكتــب املدعــي العقــاري وعنــد غيــره وأن املدعــي جــاءه بزبونــن‬\n     ‫قبــل املشــتري وأنــه جــاءه واملشــتري لرؤيــة العمــارة ودخلوهــا وذهبــا ومــن‬\n     ‫ثــم اشــتراها باملبلــغ املذكــور يف الدعــوى ومصادقتــه علــى ماذكــره‬\n     ‫املدعــي مــن اتصالــه بــه وقولــه لــه إذا الزبــون عــازم فخــذ منــه العربــون ال‬\n     ‫يهــون الرجــال علــى أســاس أن الثمــن مليــون ومائــة ألــف ريــال كــدر وملــا‬\n     ‫قــرره أهــل العلــم رحمهــم اهلل مــن أن املعــروف عرفـ ًا كاملشــروط شــرط ًا‬\n     ‫لــذا حكمــت علــى املدعــى عليــه بــأن يدفــع للمدعــي املبلــغ املدعــى بــه‬\n     ‫ســبعة وعشــرين ألفـ ًا وخمســمائة ريــال وبعــرض احلكــم علــى الطرفــن‬\n\n\n‫‪37‬‬\n\f‫قنــع بــه املدعــي ولــم يقنــع بــه املدعــى عليــه وطلــب اإلســتئناف فأفهمتــه‬\n‫باملراجعــة خــال خمســة أيــام إلســتالم نســخة مــن احلكــم وبعدهــا تبــدأ‬\n‫مــدة االعتــراض ثالثــون يومــا إذا مضــت ولــم يقــدم اعتراضــه خاللهــا‬\n‫ســقط حقــه يف االعتــراض وصــار احلكــم قطعي ـ ًا ففهــم ذلــك وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبنــا محمــد وآلــه وصحبــه أجمعــن حــرر‬\n                                                           ‫يف ‪1434/01/12‬هــ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪1434/04/08‬ه ـ عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مظهــر ًا علــى احلكــم الصــادر فيهــا مبــا نصــه احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 349707‬وتاريــخ‬\n‫‪1434/01/12‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة العامــة‬\n‫باخلــرج الشــيخ ‪ ...‬وأصدرنــا القــرار رقــم ‪ 3454614‬يف ‪1434/03/03‬ه ـ‬\n‫املتضمــن أنــه لــم يظهــر لألكثريــة مــا يوجــب املالحظــة واهلل املوفــق‬\n‫رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n‫قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه ولــه وجهــة نظــر مرفقــه ا‪.‬ه ـ‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن حــرر يف‬\n                                                               ‫‪1434/04/08‬هــ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق ‪1434/5/22‬ه ـ حضــر املدعــي املشــار ألســمه‬\n‫وهويتــه بعاليــه واســتلم املبلــغ احملكــوم بــه اعــاه وقدره ســبعة وعشــرون‬\n‫الفــا وخمســمائة ريــال مبوجــب الشــيكني األول برقــم ‪940671‬‬\n‫املســحوب علــى مصــرف ‪ ...‬فــرع ‪ ...‬بتاريــخ ‪1434/5/1‬ه ـ مببلــغ تســعة‬\n‫آالف ومائتــان ريــال والثانــي برقــم ‪ 6266‬املســحوب علــى بنــك ‪ ...‬فــرع‬\n‫‪ ...‬بتاريــخ ‪1434/5/14‬ه ـ مببلــغ ثمانيــة عشــر الفــا وثالثمائــة ريــال وبــه‬\n‫برئــت ذمــة املدعــى عليــه منــه فجــرى اثباتــه بحضــور كاتبــه ‪ ...‬وصلــى‬\n\n\n                                                                                     ‫‪38‬‬\n\f     ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه اجمعــن حــرر يف‬\n                                                                   ‫‪1434/5/22‬ه ـ ‪.‬‬\n     ‫احلمــدهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n     ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامــة بحافظــة اخلــرج العامــة املكلــف‬\n     ‫برقــم ‪ 331201640‬وتاريــخ ‪ 1434/2/18‬ه ـ املرفــق بهــا الصــك الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ )...( /‬املســجل برقــم ‪349707‬‬\n     ‫وتاريــخ ‪ 1434/1/12‬ه ـ اخلــاص بدعــوى‪ )...( /‬ضــد‪ )...( /‬وبدراســة‬\n     ‫الصــك وصــورة ضبطــه والالئحــة وأوراق املعاملــة لــم يظهــر لألكثريــة‬\n     ‫مــا يوجــب املالحظــة‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                              ‫وســلم ‪.‬‬\n\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":33,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ab0a4e5f12f6f9fe10e49ee7e6a8e95f9b9872b85ba1911bb7c63cb9aedd8c3c","normalized_text_hash":"36f971c965221edbd190974f3b1c6f399079361a85546f4eab429506d9e2ce24","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p33-349707"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
